#[cfg(unix)]
#[test]
fn release_suite_process_guard_discovers_scoped_process_cwd() {
    let tmp = TempDir::new().unwrap();
    let root = tmp.path().join("fixture-root");
    fs::create_dir_all(root.join(".fluent/work/items")).unwrap();
    let guard =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("scripts/release-test-process-guard.sh");
    let output = Command::new("bash")
        .arg(guard)
        .args([
            "bash",
            "-c",
            "cd \"$1\"; \"$2\" scheduler run --poll-seconds 60 > /dev/null 2>&1 & leak=$!; disown \"$leak\"; echo \"$leak\" > leaked.pid",
            "fixture-root",
        ])
        .arg(&root)
        .arg(env!("CARGO_BIN_EXE_fluent"))
        .env("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass")
        .env("FLUENT_RELEASE_TEST_ROOTS", &root)
        .output()
        .unwrap();

    let leaked_pid = fs::read_to_string(root.join("leaked.pid")).unwrap();
    let _ = Command::new("kill")
        .args(["-TERM", leaked_pid.trim()])
        .status();
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(!output.status.success(), "guard accepted a scoped process");
    assert!(stderr.contains("kind=fluent"), "diagnostic: {stderr}");
    let root = fs::canonicalize(root).unwrap();
    assert!(stderr.contains(&format!("root={}", root.display())));
}

#[test]
fn fluent_release_tester_uses_host_owned_process_settlement() {
    let tester_yaml =
        fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(".fluent/tester.yaml"))
            .unwrap();
    let config: serde_yaml::Value = serde_yaml::from_str(&tester_yaml).unwrap();
    let commands = config["commands"].as_sequence().unwrap();

    assert_eq!(commands.len(), 2);
    assert!(commands.iter().all(|command| {
        command["reject_process_leaks"]
            .as_bool()
            .is_some_and(|enabled| enabled)
    }));
    assert!(!tester_yaml.contains("release-test-process-guard.sh"));
    assert!(!tester_yaml.contains("FLUENT_TEST_PROCESS_INVENTORY"));
    assert!(!tester_yaml.contains("mktemp -d"));
}

#[test]
fn fluent_release_tester_historical_reader_setup_is_cold_cache_safe() {
    let repository = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let source_commit = "f71d20bb11f241c9ab9ba38b401f22e692d9e19f";
    let tmp = TempDir::new().unwrap();
    let project = tmp.path().join("historical reader");
    git::run(
        &repository,
        &[
            "clone",
            "--shared",
            "--no-checkout",
            ".",
            project.to_str().unwrap(),
        ],
        "clone historical reader fixture",
    )
    .unwrap();
    let bin_dir = tmp.path().join("bin");
    // Keep dependency admission deterministic without touching any Cargo home.
    // The real helper still archives Git source and writes the binary identity.
    write_mock_executable(
        &bin_dir,
        "cargo",
        r#"#!/usr/bin/env python3
import sys
from pathlib import Path
args = sys.argv[1:]
if '--offline' in args or '--frozen' in args:
    sys.exit('historical reader dependencies are absent from the cold cache')
assert args[0] == 'build', args
assert '--locked' in args, 'historical reader must preserve its committed lockfile'
root = Path(args[args.index('--manifest-path') + 1]).parent
assert (root / 'Cargo.lock').is_file(), 'archive must include the committed lockfile'
binary = root / 'target/debug/fluent'
binary.parent.mkdir(parents=True)
binary.write_text('#!/bin/sh\nexit 0\n')
binary.chmod(0o755)
print('built historical reader with locked dependencies', file=sys.stderr)
"#,
    );
    let output = Command::new("bash")
        .arg(repository.join("tests/fixtures/build-ownership-old-reader.sh"))
        .current_dir(&project)
        .env(
            "PATH",
            format!("{}:{}", bin_dir.display(), std::env::var("PATH").unwrap()),
        )
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "cold-cache setup failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let reader_root = project.join(".scratch/ownership-old-reader");
    let binary = reader_root.join("target/debug/fluent");
    assert_eq!(
        fs::canonicalize(String::from_utf8(output.stdout).unwrap().trim()).unwrap(),
        fs::canonicalize(&binary).unwrap(),
        "helper stdout must contain only the reader path"
    );
    for file in ["Cargo.toml", "Cargo.lock", "src/main.rs"] {
        let archived = Command::new("git")
            .current_dir(&repository)
            .args(["show", &format!("{source_commit}:{file}")])
            .output()
            .unwrap();
        assert!(archived.status.success());
        assert_eq!(fs::read(reader_root.join(file)).unwrap(), archived.stdout);
    }
    let identity = read_json_path(&reader_root.join("identity.json"));
    assert_eq!(identity["source_commit"], source_commit);
    assert_eq!(
        identity["binary_sha256"],
        format!("{:x}", Sha256::digest(fs::read(binary).unwrap()))
    );
}

#[test]
fn fluent_release_tester_historical_reader_setup_fails_closed() {
    let tester_yaml =
        fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(".fluent/tester.yaml"))
            .unwrap();
    let config: serde_yaml::Value = serde_yaml::from_str(&tester_yaml).unwrap();
    let command = config["commands"][0]["command"].as_str().unwrap();

    // A successful setup is the control. Failures must stop even if the helper
    // has already printed a path, and must preserve its diagnostic and status.
    for (setup_status, prints_path) in [(0, true), (37, false), (37, true)] {
        let tmp = TempDir::new().unwrap();
        let project = tmp.path().join("tester project");
        let fixtures = project.join("tests/fixtures");
        let bin_dir = tmp.path().join("bin");
        write_mock_executable(
            &fixtures,
            "build-ownership-old-reader.sh",
            r#"#!/bin/sh
printf '%s' "$FLUENT_TEST_READER_OUTPUT"
if [ "$FLUENT_TEST_READER_STATUS" -ne 0 ]; then
    echo 'historical reader build failed' >&2
fi
exit "$FLUENT_TEST_READER_STATUS"
"#,
        );
        write_mock_executable(&bin_dir, "old reader", "#!/bin/sh\nexit 0\n");
        write_mock_executable(
            &bin_dir,
            "cargo",
            r#"#!/bin/sh
set -eu
printf '%s\n' "$*" >> "$FLUENT_TEST_CARGO_CALLS"
printf '%s\n' "${FLUENT_OWNERSHIP_OLD_BIN-unset}" >> "$FLUENT_TEST_READER_PATHS"
case "$1" in
    build) mkdir -p target/debug; touch target/debug/fluent ;;
    nextest) exit 0 ;;
    *) exit 91 ;;
esac
"#,
        );
        let reader = bin_dir.join("old reader");
        let cargo_calls = tmp.path().join("cargo-calls");
        let reader_paths = tmp.path().join("reader-paths");
        // Tester executes each configured command through sh -c.
        let output = Command::new("sh")
            .args(["-c", command])
            .current_dir(&project)
            .env_remove("FLUENT_OWNERSHIP_OLD_BIN")
            .env("FLUENT_TEST_READER_STATUS", setup_status.to_string())
            .env(
                "FLUENT_TEST_READER_OUTPUT",
                if prints_path {
                    reader.to_str().unwrap()
                } else {
                    ""
                },
            )
            .env("FLUENT_TEST_CARGO_CALLS", &cargo_calls)
            .env("FLUENT_TEST_READER_PATHS", &reader_paths)
            .env(
                "PATH",
                format!("{}:{}", bin_dir.display(), std::env::var("PATH").unwrap()),
            )
            .output()
            .unwrap();
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert_eq!(output.status.code(), Some(setup_status), "{stderr}");
        if setup_status == 0 {
            let calls = fs::read_to_string(&cargo_calls).unwrap();
            let calls: Vec<_> = calls.lines().collect();
            assert_eq!(calls.len(), 3, "{calls:?}");
            assert_eq!(calls[0], "build");
            assert_eq!(calls[1], "build --features test-support");
            assert!(calls[2].starts_with("nextest run "), "{calls:?}");
            assert_eq!(
                fs::read_to_string(reader_paths).unwrap(),
                format!("{}\n", reader.display()).repeat(3),
                "every Cargo child must receive the exported reader path"
            );
        } else {
            assert!(
                stderr.contains("historical reader build failed"),
                "{stderr}"
            );
            assert!(!cargo_calls.exists(), "setup failure launched Cargo");
            assert!(!reader_paths.exists(), "setup failure reached a Rust child");
        }
    }
}

fn provider_double_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/provider-doubles")
}

fn work_item_value(project_root: &Path, id: &str) -> serde_json::Value {
    let output = fluent_cmd()
        .current_dir(project_root)
        .args(["work-item", "show", id])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "show failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).unwrap()
}

fn read_json_path(path: &Path) -> serde_json::Value {
    serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap()
}

fn write_json_path(path: &Path, value: &serde_json::Value) {
    fs::write(path, serde_json::to_string_pretty(value).unwrap()).unwrap()
}

fn skill_file_snapshot(skill_dir: &Path) -> Vec<(PathBuf, Vec<u8>)> {
    fn collect(root: &Path, dir: &Path, files: &mut Vec<(PathBuf, Vec<u8>)>) {
        let mut entries = fs::read_dir(dir)
            .unwrap()
            .map(|entry| entry.unwrap())
            .collect::<Vec<_>>();
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let path = entry.path();
            if path.is_dir() {
                collect(root, &path, files);
            } else if path
                .file_name()
                .is_some_and(|name| name != ".fluent-managed.json")
            {
                files.push((
                    path.strip_prefix(root).unwrap().to_path_buf(),
                    fs::read(path).unwrap(),
                ));
            }
        }
    }

    let mut files = Vec::new();
    collect(skill_dir, skill_dir, &mut files);
    files
}

fn bundle_digest(files: &[(PathBuf, Vec<u8>)]) -> String {
    let mut hasher = Sha256::new();
    for (path, bytes) in files {
        hasher.update(path.to_string_lossy().as_bytes());
        hasher.update([0]);
        hasher.update((bytes.len() as u64).to_be_bytes());
        hasher.update(bytes);
    }
    format!("{:x}", hasher.finalize())
}

fn complete_skill_snapshot(skill_dir: &Path) -> Vec<(PathBuf, Vec<u8>)> {
    fn collect(root: &Path, dir: &Path, files: &mut Vec<(PathBuf, Vec<u8>)>) {
        let mut entries = fs::read_dir(dir)
            .unwrap()
            .map(|entry| entry.unwrap())
            .collect::<Vec<_>>();
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let path = entry.path();
            if path.is_dir() {
                collect(root, &path, files);
            } else {
                files.push((
                    path.strip_prefix(root).unwrap().to_path_buf(),
                    fs::read(path).unwrap(),
                ));
            }
        }
    }

    let mut files = Vec::new();
    collect(skill_dir, skill_dir, &mut files);
    files
}

