#[test]
fn nested_work_routes_use_only_fixture_coders() {
    let tmp = TempDir::new().unwrap();
    let project = setup_git_project(&tmp);
    let path = format!(
        "{}:{}",
        provider_double_path().display(),
        std::env::var("PATH").unwrap()
    );
    for coder in ["claude", "codex", "pi"] {
        let work_item_id = format!("fixture-{coder}");
        fluent_cmd()
            .current_dir(&project)
            .args([
                "work-item",
                "create",
                &work_item_id,
                "--title",
                "Fixture coder",
            ])
            .env("PATH", &path)
            .assert()
            .success();
        fluent_cmd()
            .current_dir(&project)
            .args([
                "attempt",
                "create",
                &work_item_id,
                "attempt-1",
                "--write-coder",
                coder,
            ])
            .env("PATH", &path)
            .assert()
            .success();

        fluent_cmd()
            .current_dir(&project)
            .args(["attempt", "run", &work_item_id, "attempt-1", "--no-sandbox"])
            .env("PATH", &path)
            .env("FLUENT_TEST_HERMETIC_NO_SANDBOX", "1")
            .assert()
            .failure();

        let provider_stderr = project
            .join(".fluent/work/artifacts")
            .join(&work_item_id)
            .join("attempt-1/attempt-1-write-1/provider-stderr.log");
        let diagnostic = fs::read_to_string(&provider_stderr)
            .unwrap_or_else(|error| panic!("read {}: {error}", provider_stderr.display()));
        assert!(
            diagnostic.contains(&format!("test provider double blocked {coder} invocation")),
            "provider diagnostic: {diagnostic}"
        );
    }
}

