#[test]
fn init_seeds_local_preview_operating_boundary() {
    let tmp = TempDir::new().unwrap();
    let home = tmp.path().join("home");
    fs::create_dir_all(&home).unwrap();
    let project = tmp.path().join("project");
    fs::create_dir_all(&project).unwrap();

    fluent_cmd()
        .env("HOME", home.to_str().unwrap())
        .current_dir(&project)
        .arg("init")
        .assert()
        .success();

    let content = fs::read_to_string(project.join("AGENTS.md")).unwrap();
    let begin = content.find("<!-- BEGIN fluent -->").unwrap();
    let end = content[begin..].find("<!-- END fluent -->").unwrap() + begin;
    let managed = &content[begin..end];
    let normalized = managed.split_whitespace().collect::<Vec<_>>().join(" ");

    let mut offset = 0;
    for phrase in [
        "proposed Work by default",
        "`fluent work-item authorize` authorizes and queues Work",
        "`fluent scheduler run`",
        "ready Merge Candidate after successful Learning",
        "every ready candidate is inspected and landed by a human",
    ] {
        let relative = normalized[offset..]
            .find(phrase)
            .unwrap_or_else(|| panic!("managed block lacks ordered guidance: {phrase}"));
        offset += relative + phrase.len();
    }

    assert!(managed.contains("Attempts run locally in the foreground"));
    assert!(
        normalized.contains("execution starts only while a human runs `fluent scheduler run`.")
    );
    assert!(normalized.contains(
        "Post-merge review is off by default; opt in per land with \
         `fluent merge-candidate land --post-merge-review`."
    ));
    assert!(managed.contains("`fluent auto-merge`"));
    assert!(managed.contains("Fargate"));
    assert!(managed.contains("outside this path"));
    assert!(managed.contains("explicit\n  coder profile before running configured `fluent init`"));
    assert!(managed.contains("Bare `fluent init` remains available"));
    assert!(
        managed
            .contains("preflights\n  providers, and saves the writer/reviewer mapping atomically")
    );
    assert!(!managed.contains("autonomous execute → review → land"));
    assert!(!managed.contains("policy allows autonomous merging"));
}

#[test]
fn init_updates_craft_section_in_place_idempotently() {
    let tmp = TempDir::new().unwrap();
    let home = tmp.path().join("home");
    fs::create_dir_all(&home).unwrap();
    let project = tmp.path().join("project");
    fs::create_dir_all(&project).unwrap();

    let pre = "# My Project\n\nSome content.\n";
    let post = "\n## Footer\n";
    let old_block = "<!-- BEGIN fluent -->\nold craft content\n<!-- END fluent -->";
    fs::write(project.join("AGENTS.md"), format!("{pre}{old_block}{post}")).unwrap();

    fluent_cmd()
        .env("HOME", home.to_str().unwrap())
        .current_dir(&project)
        .arg("init")
        .assert()
        .success();

    let content = fs::read_to_string(project.join("AGENTS.md")).unwrap();
    assert!(
        content.starts_with(pre),
        "content before the markers must be preserved"
    );
    assert!(
        content.ends_with(post),
        "content after the markers must be preserved"
    );
    assert!(
        !content.contains("old craft content"),
        "old craft content must be replaced"
    );
    assert!(
        content.contains("<!-- BEGIN fluent -->"),
        "begin marker must be present"
    );
    assert!(
        content.contains("<!-- END fluent -->"),
        "end marker must be present"
    );
    assert_eq!(
        content.matches("<!-- BEGIN fluent -->").count(),
        1,
        "begin marker must appear exactly once"
    );
}

#[test]
fn init_names_instruction_changes_that_require_git_resolution() {
    let tmp = TempDir::new().unwrap();
    let home = tmp.path().join("home");
    fs::create_dir_all(&home).unwrap();
    let project = tmp.path().join("project");
    fs::create_dir_all(&project).unwrap();
    init_git_repo(&project);
    fs::write(project.join("AGENTS.md"), "# Agent instructions\n").unwrap();
    fs::write(
        project.join("CLAUDE.md"),
        "<!-- BEGIN fluent -->\nold guidance\n<!-- END fluent -->\n",
    )
    .unwrap();
    git::run(
        &project,
        &["add", "AGENTS.md", "CLAUDE.md"],
        "stage instructions",
    )
    .unwrap();
    git::run(
        &project,
        &["commit", "-m", "Add agent instructions"],
        "commit instructions",
    )
    .unwrap();

    let output = fluent_cmd()
        .env("HOME", home.to_str().unwrap())
        .current_dir(&project)
        .arg("init")
        .output()
        .unwrap();

    assert!(output.status.success());
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        stderr.contains("AGENTS.md") && stderr.contains("CLAUDE.md"),
        "init should name every changed instruction file: {stderr}"
    );
    assert!(
        stderr.contains("Commit or revert"),
        "init should tell the user how to resolve the changes: {stderr}"
    );
    assert!(
        stderr.contains("candidate worktrees") && stderr.contains("committed Git state"),
        "init should explain why resolution is required: {stderr}"
    );
}

