#[test]
fn work_create_snapshots_exact_managed_input_artifact_bytes() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let source = main_dir.join(".fluent/work/artifacts/evidence/transcript.bin");
    fs::create_dir_all(source.parent().unwrap()).unwrap();
    let approved = b"approved\0bytes\xff";
    fs::write(&source, approved).unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-input",
            "--title",
            "Preserve evidence",
            "--input-artifact",
            ".fluent/work/artifacts/evidence/transcript.bin",
        ])
        .assert()
        .success();

    fs::write(&source, b"changed").unwrap();
    fs::remove_file(&source).unwrap();
    let shown = read_work_show_json(&main_dir, "work-input");
    let identity = &shown["input_artifacts"][0];
    assert_eq!(
        identity["source_path"],
        ".fluent/work/artifacts/evidence/transcript.bin"
    );
    assert_eq!(
        identity["digest"],
        format!("sha256:{:x}", Sha256::digest(approved))
    );
    let snapshot = main_dir.join(identity["snapshot_path"].as_str().unwrap());
    assert_eq!(fs::read(snapshot).unwrap(), approved);

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-input", "attempt-1"])
        .assert()
        .success();
    let shown = read_work_show_json(&main_dir, "work-input");
    assert_eq!(
        shown["attempts"][0]["tasks"][0]["input_artifacts"][0]["path"],
        identity["snapshot_path"]
    );
}

#[test]
fn concurrent_same_id_work_creation_preserves_the_winners_input_snapshot() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let source = main_dir.join(".fluent/work/artifacts/evidence/input.txt");
    fs::create_dir_all(source.parent().unwrap()).unwrap();
    fs::write(&source, b"authoritative\n").unwrap();
    let binary = assert_cmd::cargo::cargo_bin("fluent");
    let mut children = Vec::new();
    for title in ["First creator", "Second creator"] {
        children.push(
            Command::new(&binary)
                .current_dir(&main_dir)
                .args([
                    "work-item",
                    "create",
                    "work-input",
                    "--title",
                    title,
                    "--input-artifact",
                    ".fluent/work/artifacts/evidence/input.txt",
                ])
                .env("FLUENT_NO_UPDATE_CHECK", "1")
                .spawn()
                .unwrap(),
        );
    }
    let statuses = children
        .into_iter()
        .map(|mut child| child.wait().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(statuses.iter().filter(|status| status.success()).count(), 1);

    let stored = WorkModelStore::new(&main_dir)
        .read_work_item("work-input")
        .unwrap();
    assert_eq!(stored.input_artifacts.len(), 1);
    assert_eq!(
        fs::read(main_dir.join(&stored.input_artifacts[0].snapshot_path)).unwrap(),
        b"authoritative\n"
    );
}

