    land_work_1(&main_dir, &bin_dir, true);

    let first = open_observation_files(&main_dir);
    assert_eq!(first.len(), 1);

    // Re-landing an already-merged candidate resumes processing idempotently.
    land_work_1(&main_dir, &bin_dir, true);

