#[test]
fn tester_sandbox_recovery_reruns_same_tester_without_writer() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-tester-recovery");
    let writer_counter = tmp.path().join("writer-count");
    let boundary_log = tmp.path().join("tester-recovery-boundary.log");
    let harness_repaired = tmp.path().join("tester-harness-repaired");
    write_mock_claude(
        &bin_dir,
        &format!(
            r##"#!/bin/bash
PROMPT=""
NEXT_IS_PROMPT=0
for arg in "$@"; do
  if [ "$NEXT_IS_PROMPT" = 1 ]; then PROMPT="$arg"; break; fi
  if [ "$arg" = "-p" ]; then NEXT_IS_PROMPT=1; fi
done
if printf '%s' "$PROMPT" | grep -q "You are the Learner"; then
  DRAFT=$(printf '%s' "$PROMPT" | grep -o '/[^ ]*follow-up-draft.json' | head -1)
  mkdir -p "$(dirname "$DRAFT")"
  printf '%s\n' '{{"learning_summary":"none","follow_ups":[]}}' > "$DRAFT"
  exit 0
fi
case "$PWD" in
  */work-*-work-1-attempt-1)
    count=$(cat '{counter}' 2>/dev/null || echo 0)
    count=$((count + 1))
    echo "$count" > '{counter}'
    printf 'writer output\n' > writer-output.txt
    git add writer-output.txt
    git commit -m "Add writer output" >/dev/null 2>&1
    ;;
  *) printf 'Verdict: pass\n\nLooks good.\n' > review.md ;;
esac
exit 0
"##,
            counter = writer_counter.display()
        ),
    );
    fs::write(
        main_dir.join(".fluent/tester.yaml"),
        format!(
            "commands:\n  - command: \"if [ -f '{}' ]; then echo 'ok repaired'; else printf 'sandbox-exec: sandbox_apply: Operation not permitted\\n' >&2; exit 1; fi # swift test\"\n    test_harness: shell-harness\n",
            harness_repaired.display()
        ),
    )
    .unwrap();
    git::run(
        &main_dir,
        &["add", ".fluent/tester.yaml"],
        "stage broken Tester fixture",
    )
    .unwrap();
    git::run(
        &main_dir,
        &["commit", "-m", "Configure broken Tester fixture"],
        "commit broken Tester fixture",
    )
    .unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-1",
            "--title",
            "Tester recovery",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    let _first = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_MAX_TASK_RETRIES", "0")
        .output()
        .unwrap();
    let paused = work_item_value(&main_dir, "work-1");
    assert_eq!(
        paused["attempts"][0]["status"],
        "needs-user",
        "broken extractor must pause the Attempt: stdout={} stderr={} state={paused}",
        String::from_utf8_lossy(&_first.stdout),
        String::from_utf8_lossy(&_first.stderr),
    );
    assert_eq!(paused["attempts"][0]["pause_kind"], "tester-harness");
    assert_eq!(paused["attempts"][0]["pause_recovery"], "tester-no-sandbox");
    let recovery = "fluent queue resume work-1 --attempt attempt-1 --no-sandbox";
    assert_eq!(paused["next-action"], recovery);
    let current_handoff = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/needs-user.md");
    assert!(
        fs::read_to_string(current_handoff)
            .unwrap()
            .contains(recovery)
    );
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["status"])
        .assert()
        .success()
        .stderr(predicate::str::contains(recovery));
    assert_eq!(fs::read_to_string(&writer_counter).unwrap().trim(), "1");
    write_mock_sandbox_exec(&bin_dir);
    fs::write(&harness_repaired, "repaired\n").unwrap();
    let resumed = fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "attempt",
            "run",
            "--tester-no-sandbox",
            "work-1",
            "attempt-1",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_MAX_TASK_RETRIES", "0")
        .env("FLUENT_TEST_TESTER_BOUNDARY_LOG", &boundary_log)
        .output()
        .unwrap();
    assert!(
        resumed.status.success(),
        "repairing the Tester must resume the same Attempt: stdout={} stderr={}",
        String::from_utf8_lossy(&resumed.stdout),
        String::from_utf8_lossy(&resumed.stderr)
    );
    assert!(
        String::from_utf8_lossy(&resumed.stderr).contains(
            "Tester recovery   disabling Fluent's sandbox for exact Task attempt-1-tester"
        ),
        "the scheduler child capability must reach the exact Tester executor: stderr={}",
        String::from_utf8_lossy(&resumed.stderr)
    );
    assert_eq!(
        fs::read_to_string(&writer_counter).unwrap().trim(),
        "1",
        "resuming a Tester harness pause must not rerun the completed Writer"
    );
    assert_eq!(
        fs::read_to_string(&boundary_log).unwrap(),
        "run_with_sandbox_profile sandboxed=false\n",
        "the internal recovery capability applies to the paused Tester boundary"
    );
}

