#[test]
fn work_task_run_write_auth_rejection_pauses_attempt_after_one_retry() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    seed_project_expertise(&main_dir);

    let bin_dir = tmp.path().join("bin-write-auth-401");
    let counter_file = tmp.path().join("write-auth-invocation-count");
    write_mock_claude(
        &bin_dir,
        &format!(
            r##"#!/bin/bash
HAS_PROMPT=0
for arg in "$@"; do
  if [ "$arg" = "-p" ]; then HAS_PROMPT=1; break; fi
done
if [ "$HAS_PROMPT" = 0 ]; then exit 0; fi
COUNTER='{counter}'
count=$(cat "$COUNTER" 2>/dev/null || echo 0)
count=$((count + 1))
printf '%s' "$count" > "$COUNTER"
if [ "$3" = "ok" ]; then exit 0; fi
echo '{{"type":"result","api_error_status":401,"request_id":"req-test-401"}}'
exit 1
"##,
            counter = counter_file.display()
        ),
    );
    write_mock_executable(
        &bin_dir,
        "security",
        "#!/bin/sh\nprintf '%s\\n' '{\"claudeAiOauth\":{\"accessToken\":\"fixture-token\"}}'\n",
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Run task"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-write-1",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_TEST_ALLOW_CREDENTIAL_FIXTURES", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "2")
        .assert()
        .failure()
        .stderr(predicate::str::contains("401"))
        .stderr(predicate::str::contains("re-authenticate"));

    let invocations: u32 = fs::read_to_string(&counter_file)
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    assert_eq!(
        invocations, 3,
        "expected 3 invocations: original 401, refresh probe, one retry"
    );

    let value = read_work_show_json(&main_dir, "work-1");
    assert_eq!(
        value["attempts"][0]["status"], "needs-user",
        "attempt should pause at needs-user on auth rejection"
    );

    let handoff_path =
        main_dir.join(".fluent/work/artifacts/work-1/attempt-1/needs-user-attempt-1-write-1.md");
    assert!(handoff_path.exists(), "handoff file should exist");
    let handoff = fs::read_to_string(&handoff_path).unwrap();
    assert!(
        handoff.contains("re-authenticate"),
        "handoff should instruct user to re-authenticate: {handoff}"
    );
}

#[test]
fn final_tester_error_pauses_same_attempt_after_reviewers() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);

    create_completed_work_attempt(&tmp, &main_dir);
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["review", "work-1", "attempt-1"])
        .assert()
        .success();
    plan_final_tester_after_passing_reviews(&main_dir);

    let artifact_dir = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-tester");
    let blocker = artifact_dir.join("tester-results.json");
    let _ = fs::remove_file(&blocker);
    fs::create_dir_all(&blocker).unwrap();

    let bin_dir = tmp.path().join("bin-tester");
    write_mock_claude(&bin_dir, "#!/bin/bash\nexit 0\n");

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-tester",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_MAX_TASK_RETRIES", "2")
        .assert()
        .failure();

    let value = read_work_show_json(&main_dir, "work-1");
    let tester_task = value["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == "attempt-1-tester")
        .unwrap();
    assert_eq!(
        value["attempts"][0]["status"], "needs-user",
        "attempt should pause at needs-user after persistent tester error"
    );
    assert_eq!(tester_task["status"], "needs-user");
    assert_eq!(
        value["attempts"][0]["pause_kind"], "tester-harness",
        "persistent Tester errors must remain resumable"
    );
    assert!(
        value["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|task| task["kind"] == "review")
            .all(|task| task["status"] == "complete"),
        "the final Tester starts only after every Reviewer completes: {}",
        value["attempts"][0]["tasks"]
    );
}

#[test]
fn work_task_run_tester_recovers_when_error_is_transient() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);

    let attempt_file = tmp.path().join("tester-attempt-count");
    let artifact_dir = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-tester");
    let blocker = artifact_dir.join("tester-results.json");

    let tester_yaml = main_dir.join(".fluent/tester.yaml");
    fs::create_dir_all(tester_yaml.parent().unwrap()).unwrap();
    fs::write(
        &tester_yaml,
        format!(
            "commands:\n  - command: |\n      \
             if [ \"$FLUENT_TEST_MUTATE_DURING_RETRY\" != 1 ]; then exit 0; fi\n        \
             if [ ! -f '{attempt_file}' ]; then\n        \
             printf '1' > '{attempt_file}'\n        \
             printf 'tester mutation\\n' > README.md\n        \
             mkdir -p '{blocker}'\n      \
             else\n        \
             [ \"$(cat README.md)\" = test ] || exit 99\n        \
             rm -rf '{blocker}'\n      \
             fi\n    \
             test_harness: shell-harness\n",
            attempt_file = attempt_file.display(),
            blocker = blocker.display(),
        ),
    )
    .unwrap();
    git::run(&main_dir, &["add", ".fluent/tester.yaml"], "stage").unwrap();
    git::run(&main_dir, &["commit", "-m", "Add tester.yaml"], "commit").unwrap();

    create_completed_work_attempt(&tmp, &main_dir);
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["review", "work-1", "attempt-1"])
        .assert()
        .success();
    plan_final_tester_after_passing_reviews(&main_dir);

    let bin_dir = tmp.path().join("bin-tester");
    write_mock_claude(&bin_dir, "#!/bin/bash\nexit 0\n");

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-tester",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_TEST_MUTATE_DURING_RETRY", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "2")
        .assert()
        .success();

    let value = read_work_show_json(&main_dir, "work-1");
    let tester_task = value["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == "attempt-1-tester")
        .unwrap();
    assert_eq!(
        tester_task["status"], "complete",
        "tester task should complete after recovery on retry"
    );
    assert_ne!(
        value["attempts"][0]["status"], "failed",
        "attempt should not be failed after successful retry"
    );
    assert_ne!(
        value["attempts"][0]["status"], "needs-user",
        "attempt should not be needs-user after successful retry"
    );
    let candidate_workspace = main_dir.join(
        value["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["kind"] == "write" && task["status"] == "complete")
            .unwrap()["output"]["workspace_path"]
            .as_str()
            .unwrap(),
    );
    assert_eq!(
        fs::read_to_string(candidate_workspace.join("README.md")).unwrap(),
        "test",
        "the first launch's tracked mutation must be restored before retry"
    );
    assert!(artifact_dir.join("candidate-mutation.json").is_file());
}

#[test]
fn work_task_run_tester_restores_tracked_candidate_mutations_and_keeps_evidence() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);

    fs::write(
        main_dir.join(".fluent/tester.yaml"),
        "commands:\n  - command: \"if [ \\\"$FLUENT_TEST_MUTATE_CANDIDATE\\\" = 1 ]; then printf 'tester mutation\\n' > README.md; printf 'cache\\n' > tester-output.tmp; exit 42; fi\"\n    test_harness: shell-harness\n",
    )
    .unwrap();
    fs::write(
        main_dir.join(".fluent/extract-tester-results"),
        "#!/bin/sh\necho '[{\"id\":\"suite::fails\",\"test_harness\":\"shell-harness\",\"status\":\"fail\",\"duration_ms\":null,\"failure_excerpt\":\"expected failure\"}]'\n",
    )
    .unwrap();
    git::run(
        &main_dir,
        &[
            "add",
            ".fluent/tester.yaml",
            ".fluent/extract-tester-results",
        ],
        "stage mutating tester",
    )
    .unwrap();
    git::run(
        &main_dir,
        &["commit", "-m", "Add mutating tester"],
        "commit mutating tester",
    )
    .unwrap();

    create_completed_work_attempt(&tmp, &main_dir);
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["review", "work-1", "attempt-1"])
        .assert()
        .success();
    plan_final_tester_after_passing_reviews(&main_dir);

    let before = read_work_show_json(&main_dir, "work-1");
    let candidate_workspace = PathBuf::from(
        before["attempts"][0]["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["kind"] == "write" && task["status"] == "complete")
            .unwrap()["output"]["workspace_path"]
            .as_str()
            .unwrap(),
    );
    let candidate_workspace = main_dir.join(candidate_workspace);
    let readme_before = fs::read(candidate_workspace.join("README.md")).unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-tester",
            "--no-sandbox",
        ])
        .env("FLUENT_TEST_MUTATE_CANDIDATE", "1")
        .env("FLUENT_MAX_TASK_RETRIES", "0")
        .assert()
        .success();

    assert_eq!(
        fs::read(candidate_workspace.join("README.md")).unwrap(),
        readme_before,
        "the host must restore tracked files changed by Tester commands"
    );
    let tracked_status = git::run_stdout(
        &candidate_workspace,
        &["status", "--porcelain", "--untracked-files=no"],
        "read tracked candidate status",
    )
    .unwrap();
    assert!(
        tracked_status.is_empty(),
        "the Tester must leave the candidate's tracked state clean: {tracked_status}"
    );
    assert_eq!(
        fs::read_to_string(candidate_workspace.join("tester-output.tmp")).unwrap(),
        "cache\n",
        "tracked restoration must not delete untracked Tester outputs"
    );

    let artifact_dir = main_dir.join(".fluent/work/artifacts/work-1/attempt-1/attempt-1-tester");
    let results: serde_json::Value =
        serde_json::from_slice(&fs::read(artifact_dir.join("tester-results.json")).unwrap())
            .unwrap();
    assert_eq!(results["commands"][0]["exit_code"], 42);
    assert!(artifact_dir.join("commands/0-stdout.log").is_file());
    assert!(artifact_dir.join("commands/0-stderr.log").is_file());
    let mutation: serde_json::Value =
        serde_json::from_slice(&fs::read(artifact_dir.join("candidate-mutation.json")).unwrap())
            .unwrap();
    assert_eq!(mutation["candidate_commit"], results["candidate_commit"]);
    assert_eq!(mutation["restored"], true);
    assert!(
        mutation["tracked_status"]
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| entry.as_str().unwrap().contains("README.md"))
    );
}

