fn git_head(repo: &Path) -> String {
    git::run_stdout(repo, &["rev-parse", "HEAD"], "get HEAD").unwrap()
}

/// Poll `condition` until it returns true or `timeout` elapses. Returns whether
/// it became true, so callers can assert a deadline-bounded expectation without
/// an unbounded sleep.
fn poll_until(timeout: std::time::Duration, mut condition: impl FnMut() -> bool) -> bool {
    let deadline = std::time::Instant::now() + timeout;
    loop {
        if condition() {
            return true;
        }
        if std::time::Instant::now() >= deadline {
            return false;
        }
        std::thread::sleep(std::time::Duration::from_millis(50));
    }
}

fn git_common_dir(repo: &Path) -> PathBuf {
    let path_str = git::run_stdout(
        repo,
        &["rev-parse", "--git-common-dir"],
        "get git common dir",
    )
    .unwrap();
    let path = PathBuf::from(&path_str);
    if path.is_absolute() {
        path
    } else {
        repo.join(path)
    }
}

fn commit_file(repo: &Path, path: &str, content: &str, message: &str) {
    fs::write(repo.join(path), content).unwrap();
    git::run(repo, &["add", path], "stage file").unwrap();
    git::run(repo, &["commit", "-m", message], "commit").unwrap();
}

const PROVIDER_READINESS_MOCK_PRELUDE: &str = r##"#!/bin/bash

write_mock_review_inspection() {
    status="$?"
    prompt=''
    for arg in "$@"; do
        case "$arg" in
            *'"candidate-commit"'*) prompt="$arg" ;;
        esac
    done
    if [ -n "$prompt" ] && [ "$status" -eq 0 ] && [ "${FLUENT_TEST_SKIP_MOCK_REVIEW_INSPECTION:-0}" != 1 ] && [ -f review.md ] && grep -qi '^Verdict: pass' review.md && [ ! -f review-inspection.json ]; then
        candidate="$(printf '%s\n' "$prompt" | sed -n 's/^- Workspace: //p' | head -1)"
        if [ -z "$candidate" ]; then
            candidate="$(printf '%s\n' "$prompt" | sed -n 's/^Review the codebase at \(.*\)\.$/\1/p' | head -1)"
        fi
        commit="$(printf '%s\n' "$prompt" | sed -n 's/^[[:space:]]*"candidate-commit": "\([^"]*\)",$/\1/p' | head -1)"
        role="$(printf '%s\n' "$prompt" | sed -n 's/^[[:space:]]*"role": "\([^"]*\)",$/\1/p' | head -1)"
        inspected="$(git -C "$candidate" ls-tree -r --name-only "$commit" | head -1)"
        absolute="$candidate/$inspected"
        jq -n \
            --arg commit "$commit" \
            --arg role "$role" \
            --arg path "$inspected" \
            '{"schema-version": 1, "candidate-commit": $commit, role: $role, inspections: [{path: $path, summary: "Synthetic reviewer inspected this tracked candidate file."}]}' \
            > review-inspection.json
        jq -cn \
            --arg absolute "$absolute" \
            '{type: "assistant", message: {content: [{type: "tool_use", id: "mock-review-read", name: "Read", input: {file_path: $absolute}}]}}'
        jq -cn \
            '{type: "user", message: {content: [{type: "tool_result", tool_use_id: "mock-review-read", content: "synthetic source"}]}}'
    fi
    return "$status"
}

trap 'write_mock_review_inspection "$@"' EXIT

if [ "$1 $2 $3" = "auth status --json" ]; then
    printf '{"loggedIn":true}\n'
    exit 0
fi

if [ "$1" = "--version" ]; then
    printf '2.1.211 (Claude Code)\n'
    exit 0
fi

"##;

fn write_mock_claude(bin_dir: &Path, script: &str) {
    fs::create_dir_all(bin_dir).unwrap();

    let script_body = script.strip_prefix("#!/bin/bash\n").unwrap_or(script);
    let combined = format!("{}{}", PROVIDER_READINESS_MOCK_PRELUDE, script_body);

    let claude_path = bin_dir.join("claude");
    fs::write(&claude_path, &combined).unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&claude_path, fs::Permissions::from_mode(0o755)).unwrap();
    }

    let sandbox_path = bin_dir.join("sandbox-exec");
    fs::write(&sandbox_path, "#!/bin/bash\nexit 1\n").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&sandbox_path, fs::Permissions::from_mode(0o755)).unwrap();
    }
}

