#[test]
fn queue_add_rejects_suspended_attempt_and_pending_candidate() {
    use fluent::work_model::{
        AttemptReviewState, AttemptStatus, MergeCandidateMergeStatus, TaskOutput, TaskStatus,
        WorkItem, WorkModelStore, WorkspaceAccess, WorkspaceRef,
    };

    // A Work Item whose Attempt is suspended at needs-user.
    let suspended = TempDir::new().unwrap();
    {
        let store = WorkModelStore::new(suspended.path());
        let mut item = WorkItem::planned("wi-susp", "Suspended");
        item.add_initial_attempt("attempt-1").unwrap();
        item.attempts[0].status = AttemptStatus::NeedsUser;
        item.attempts[0].tasks[0].status = TaskStatus::NeedsUser;
        store.create_work_item(&item).unwrap();
    }
    fluent_cmd()
        .current_dir(suspended.path())
        .args(["queue", "add", "wi-susp"])
        .assert()
        .failure()
        .stderr(
            predicate::str::contains("needs-user").and(predicate::str::contains(
                "fluent queue resume wi-susp --attempt attempt-1",
            )),
        );
    assert!(
        !suspended
            .path()
            .join(".fluent/work/queue/wi-susp.json")
            .exists()
    );

    // A Work Item whose Merge Candidate is pending land.
    let pending = TempDir::new().unwrap();
    {
        let store = WorkModelStore::new(pending.path());
        let mut item = WorkItem::planned("wi-pend", "Pending land");
        item.add_initial_attempt("attempt-1").unwrap();
        let attempt = item.attempts.last_mut().unwrap();
        let task = attempt.tasks.last_mut().unwrap();
        task.status = TaskStatus::Complete;
        task.workspace_access = WorkspaceAccess {
            reads: vec![WorkspaceRef {
                id: "target".to_string(),
                path: ".".to_string(),
            }],
            writes: vec![WorkspaceRef {
                id: "candidate".to_string(),
                path: "../work-wi-pend-attempt-1".to_string(),
            }],
        };
        task.output = Some(TaskOutput {
            workspace_id: "candidate".to_string(),
            workspace_path: "../work-wi-pend-attempt-1".to_string(),
            source_branch: "main".to_string(),
            base_commit: None,
            commit: "abc123".to_string(),
            no_change: None,
            learner_canonicalization: None,
        });
        attempt.status = AttemptStatus::Complete;
        attempt.review_state = Some(AttemptReviewState::Passed);
        item.create_or_get_merge_candidate("attempt-1").unwrap();
        assert_eq!(
            item.merge_candidates[0].merge_state.status,
            MergeCandidateMergeStatus::Pending
        );
        store.create_work_item(&item).unwrap();
    }
    fluent_cmd()
        .current_dir(pending.path())
        .args(["queue", "add", "wi-pend"])
        .assert()
        .failure()
        .stderr(predicate::str::contains("pending land"));
    assert!(
        !pending
            .path()
            .join(".fluent/work/queue/wi-pend.json")
            .exists()
    );
}

#[test]
fn queue_resume_records_exact_authorization_and_is_idempotent() {
    use fluent::queue::{self, DispatchStatus};
    use fluent::work_model::{AttemptStatus, PauseKind, TaskStatus, WorkItem, WorkModelStore};

    let tmp = TempDir::new().unwrap();
    let store = WorkModelStore::new(tmp.path());
    let mut item = WorkItem::planned("wi-resume", "Resume");
    item.add_initial_attempt("attempt-1").unwrap();
    store.create_work_item(&item).unwrap();
    queue::add(tmp.path(), "wi-resume", Some(2)).unwrap();
    queue::claim(tmp.path(), "wi-resume", "attempt-1")
        .unwrap()
        .unwrap();
    store
        .mutate_work_item("wi-resume", |item| {
            let attempt = &mut item.attempts[0];
            attempt.status = AttemptStatus::NeedsUser;
            attempt.pause_kind = Some(PauseKind::WriterCompletion);
            attempt.tasks[0].status = TaskStatus::NeedsUser;
            Ok(())
        })
        .unwrap();
    queue::reconcile_active(tmp.path(), "wi-resume", DispatchStatus::NeedsUser).unwrap();

    fluent_cmd()
        .current_dir(tmp.path())
        .args([
            "queue",
            "resume",
            "wi-resume",
            "--attempt",
            "attempt-1",
            "--no-sandbox",
        ])
        .assert()
        .failure()
        .stderr(predicate::str::contains("Tester no-sandbox recovery"));
    assert_eq!(
        queue::read_ledger(tmp.path(), "wi-resume")
            .unwrap()
            .unwrap()
            .dispatches
            .len(),
        1,
        "a rejected no-sandbox approval must not mutate the queue"
    );

    fluent_cmd()
        .current_dir(tmp.path())
        .args([
            "queue",
            "resume",
            "wi-resume",
            "--attempt",
            "attempt-1",
            "--priority",
            "7",
        ])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Queued resume of Attempt attempt-1 for Work Item wi-resume",
        ));

    let ledger = queue::read_ledger(tmp.path(), "wi-resume")
        .unwrap()
        .unwrap();
    assert_eq!(ledger.dispatches.len(), 2);
    assert_eq!(ledger.dispatches[0].status, DispatchStatus::NeedsUser);
    let resume = ledger.active().unwrap();
    assert_eq!(resume.bound_attempt_id.as_deref(), Some("attempt-1"));
    assert_eq!(resume.resume_of_dispatch_id.as_deref(), Some("dispatch-1"));
    assert_eq!(resume.priority, 7);

    fluent_cmd()
        .current_dir(tmp.path())
        .args(["queue", "resume", "wi-resume", "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("is already queued"));
    assert_eq!(
        queue::read_ledger(tmp.path(), "wi-resume")
            .unwrap()
            .unwrap()
            .dispatches
            .len(),
        2
    );

    fluent_cmd()
        .current_dir(tmp.path())
        .args(["status"])
        .assert()
        .success()
        .stdout(predicate::str::contains("Execution is stopped"))
        .stderr(predicate::str::contains("→ Next: fluent scheduler run"))
        .stderr(predicate::str::contains("queue resume").not());
}

#[test]
fn queue_resume_accepts_verified_uncertain_review_pause() {
    use fluent::queue::{self, DispatchStatus};
    use fluent::work_model::{
        AttemptReviewState, PauseKind, TaskKind, TaskOutput, TaskStatus, WorkItem, WorkModelStore,
    };

    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let store = WorkModelStore::new(&main_dir);
    let mut item = WorkItem::planned("wi-uncertain", "Retry uncertain reviewer");
    item.add_initial_attempt("attempt-1").unwrap();
    store.create_work_item(&item).unwrap();
    queue::add(&main_dir, "wi-uncertain", None).unwrap();
    queue::claim(&main_dir, "wi-uncertain", "attempt-1")
        .unwrap()
        .unwrap();

    let workspace_path =
        fluent::work_model::initial_candidate_workspace_path("wi-uncertain", "attempt-1");
    let workspace = main_dir
        .parent()
        .unwrap()
        .join(Path::new(&workspace_path).file_name().unwrap());
    git::run(
        &main_dir,
        &[
            "worktree",
            "add",
            "-q",
            "-b",
            "work/uncertain-review",
            workspace.to_str().unwrap(),
            "HEAD",
        ],
        "create uncertain-review candidate",
    )
    .unwrap();
    let candidate = git::run_stdout(&workspace, &["rev-parse", "HEAD"], "candidate").unwrap();
    store
        .mutate_work_item("wi-uncertain", |item| {
            let writer = &mut item.attempts[0].tasks[0];
            writer.status = TaskStatus::Complete;
            writer.output = Some(TaskOutput {
                workspace_id: "candidate".to_string(),
                workspace_path: workspace_path.clone(),
                source_branch: "work/uncertain-review".to_string(),
                base_commit: None,
                commit: candidate.clone(),
                no_change: None,
                learner_canonicalization: None,
            });
            item.add_review_tasks("attempt-1", fluent::review::REVIEWERS)?;
            Ok(())
        })
        .unwrap();
    store
        .mutate_work_item("wi-uncertain", |item| {
            let attempt = &mut item.attempts[0];
            for task in &mut attempt.tasks {
                if task.kind == TaskKind::Review {
                    task.status = TaskStatus::Complete;
                }
            }
            attempt.review_state = Some(AttemptReviewState::Uncertain);
            fluent::work_model::suspend_attempt(attempt, PauseKind::Uncertain);
            Ok(())
        })
        .unwrap();
    let stored = store.read_work_item("wi-uncertain").unwrap();
    for task in stored.attempts[0]
        .tasks
        .iter()
        .filter(|task| task.kind == TaskKind::Review)
    {
        let directory = main_dir.join(&task.artifact_area.as_ref().unwrap().path);
        fs::create_dir_all(&directory).unwrap();
        let verdict = if task.role == "skills" {
            "UNCERTAIN"
        } else {
            "PASS"
        };
        fs::write(directory.join("review.md"), format!("Verdict: {verdict}\n")).unwrap();
    }
    queue::reconcile_active(&main_dir, "wi-uncertain", DispatchStatus::NeedsUser).unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["queue", "resume", "wi-uncertain", "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Queued resume of Attempt attempt-1 for Work Item wi-uncertain",
        ));
    let ledger = queue::read_ledger(&main_dir, "wi-uncertain")
        .unwrap()
        .unwrap();
    assert_eq!(ledger.dispatches.len(), 2);
    assert_eq!(
        ledger.active().unwrap().bound_attempt_id.as_deref(),
        Some("attempt-1")
    );
}

