#[test]
fn retired_commit_style_legacy_projection_rejects_unsafe_frontiers() {
    use fluent::work_model::{ArtifactRef, work_artifact_path};

    let reassigned = make_legacy_omitted_gate_index_binary_fixture();
    WorkModelStore::new(&reassigned.project_root)
        .mutate_work_item("work-1", |item| {
            let gate = item.attempts[0].tasks[1]
                .input_artifacts
                .iter_mut()
                .find(|artifact| artifact.path.ends_with("/candidate-gate.json"))
                .unwrap();
            gate.producer_id = "attempt-1-write-other".to_string();
            Ok(())
        })
        .unwrap();
    assert_legacy_gate_index_public_recovery_rejected(&reassigned, "not bound");

    let noncanonical = make_legacy_omitted_gate_index_binary_fixture();
    WorkModelStore::new(&noncanonical.project_root)
        .mutate_work_item("work-1", |item| {
            let gate = item.attempts[0].tasks[1]
                .input_artifacts
                .iter_mut()
                .find(|artifact| artifact.path.ends_with("/candidate-gate.json"))
                .unwrap();
            gate.path = gate
                .path
                .replace("/candidate-gate.json", "/nested/../candidate-gate.json");
            Ok(())
        })
        .unwrap();
    assert_legacy_gate_index_public_recovery_rejected(&noncanonical, "not bound");

    let extra = make_legacy_omitted_gate_index_binary_fixture();
    WorkModelStore::new(&extra.project_root)
        .mutate_work_item("work-1", |item| {
            item.attempts[0].tasks[1].input_artifacts.push(ArtifactRef {
                producer_id: "attempt-1-review-tests".to_string(),
                path: work_artifact_path("work-1", "attempt-1", "attempt-1-review-tests/review.md"),
            });
            Ok(())
        })
        .unwrap();
    assert_legacy_gate_index_public_recovery_rejected(&extra, "inputs do not match");

    let changed_gate = make_legacy_omitted_gate_index_binary_fixture();
    let mut gate: fluent::candidate_gate::CandidateGateEvidence =
        serde_json::from_slice(&fs::read(&changed_gate.gate_path).unwrap()).unwrap();
    gate.candidate_commit = "changed-candidate".to_string();
    fs::write(
        &changed_gate.gate_path,
        serde_json::to_vec_pretty(&gate).unwrap(),
    )
    .unwrap();
    assert_legacy_gate_index_public_recovery_rejected(&changed_gate, "names candidate");

    let changed_hook = make_legacy_omitted_gate_index_binary_fixture();
    fs::write(
        &changed_hook.log_path,
        format!(
            "commit {} contains a prohibited Co-Authored-By trailer\n",
            changed_hook.candidate
        ),
    )
    .unwrap();
    assert_legacy_gate_index_public_recovery_rejected(
        &changed_hook,
        "unknown retired commit-style hook diagnostic",
    );

    let drifted = make_legacy_omitted_gate_index_binary_fixture();
    fs::write(drifted.workspace.join("later.txt"), "later\n").unwrap();
    git::run(
        &drifted.workspace,
        &["add", "later.txt"],
        "stage public legacy candidate drift",
    )
    .unwrap();
    git::run(
        &drifted.workspace,
        &[
            "commit",
            "-q",
            "-m",
            "Add later change",
            "-m",
            "- Move the candidate beyond the stored gate",
        ],
        "commit public legacy candidate drift",
    )
    .unwrap();
    assert_legacy_gate_index_public_recovery_rejected(&drifted, "not clean and unchanged");
}

#[test]
fn retired_commit_style_resume_is_idempotent_across_execution_paths() {
    struct FixtureQueueRunner {
        bin_dir: PathBuf,
    }

    impl fluent::scheduler::AttemptRunner for FixtureQueueRunner {
        fn run(
            &self,
            project_root: &Path,
            work_item_id: &str,
            attempt_id: &str,
            _tester_no_sandbox: bool,
        ) -> anyhow::Result<fluent::scheduler::AttemptOutcome> {
            let output = fluent_cmd()
                .current_dir(project_root)
                .args(["attempt", "run", work_item_id, attempt_id, "--no-sandbox"])
                .env("PATH", mock_path(&self.bin_dir))
                .output()?;
            anyhow::ensure!(
                output.status.success(),
                "queued retired-style recovery failed: stdout={} stderr={}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            fluent::scheduler::classify_attempt_outcome(project_root, work_item_id, attempt_id)
        }
    }

    let fixture = make_retired_commit_style_binary_fixture();
    let bin_dir = fixture
        .project_root
        .parent()
        .unwrap()
        .join("bin-retired-idempotent");
    write_mock_claude(
        &bin_dir,
        &learner_mock_script(r#"{"learning_summary":"learned","follow_ups":[]}"#),
    );

    fluent_cmd()
        .current_dir(&fixture.project_root)
        .args(["queue", "resume", "work-1", "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains("Queued resume"));
    let dispatch = fluent::scheduler::pick_next_queued(&fixture.project_root)
        .unwrap()
        .expect("retired-style resume should be queued");
    fluent::scheduler::dispatch_one(
        &fixture.project_root,
        &dispatch,
        &FixtureQueueRunner {
            bin_dir: bin_dir.clone(),
        },
    )
    .unwrap();

    let after_queued = WorkModelStore::new(&fixture.project_root)
        .read_work_item("work-1")
        .unwrap();
    let attempt = &after_queued.attempts[0];
    assert_eq!(
        attempt.status,
        fluent::work_model::AttemptStatus::Complete,
        "pause={:?} tasks={:?}",
        attempt.pause_kind,
        attempt
            .tasks
            .iter()
            .map(|task| (&task.id, task.kind, task.status.clone()))
            .collect::<Vec<_>>()
    );
    let tester = attempt
        .tasks
        .iter()
        .find(|task| task.kind == fluent::work_model::TaskKind::Tester)
        .expect("recovered candidate runs the final Tester");
    assert_eq!(tester.status, fluent::work_model::TaskStatus::Complete);
    let tester_results = serde_json::from_slice::<serde_json::Value>(
        &fs::read(
            fixture
                .project_root
                .join(&tester.artifact_area.as_ref().unwrap().path)
                .join("tester-results.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert!(
        tester_results["tests"]
            .as_array()
            .unwrap()
            .iter()
            .any(|test| { test["id"] == "tests/required-behavior.sh" && test["status"] == "pass" })
    );
    assert!(
        attempt
            .learning
            .as_ref()
            .is_some_and(fluent::work_model::AttemptLearning::is_succeeded)
    );
    let merge_candidate = after_queued
        .merge_candidates
        .iter()
        .find(|candidate| candidate.attempt_id == "attempt-1")
        .expect("recovered Attempt creates a Merge Candidate");
    assert_eq!(merge_candidate.candidate_commit, fixture.candidate);
    assert!(merge_candidate.ready_at.is_some());
    let receipt = attempt
        .artifacts
        .iter()
        .find(|artifact| artifact.path.ends_with("/reclassification.json"))
        .expect("queued recovery records its reclassification")
        .clone();
    let receipt_before = fs::read(fixture.project_root.join(&receipt.path)).unwrap();
    let tasks_before = attempt.tasks.clone();
    let candidate_head_before = git::run_stdout(
        &fixture.workspace,
        &["rev-parse", "HEAD"],
        "read candidate after queued recovery",
    )
    .unwrap();
    let candidate_history_before = git::run_stdout(
        &fixture.workspace,
        &["rev-list", "--reverse", "HEAD"],
        "read candidate history after queued recovery",
    )
    .unwrap();

    fluent_cmd()
        .current_dir(&fixture.project_root)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .assert()
        .success();
    let after = WorkModelStore::new(&fixture.project_root)
        .read_work_item("work-1")
        .unwrap();
    assert_eq!(
        after.attempts[0]
            .artifacts
            .iter()
            .filter(|artifact| artifact.path.ends_with("/reclassification.json"))
            .count(),
        1
    );
    assert_eq!(
        after.attempts[0]
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Write)
            .count(),
        2
    );
    assert_eq!(
        after.attempts[0]
            .tasks
            .iter()
            .filter(|task| task.kind == fluent::work_model::TaskKind::Review)
            .count(),
        fluent::review::REVIEWERS.len()
    );
    assert_eq!(after.attempts[0].tasks, tasks_before);
    assert_eq!(
        fs::read(fixture.project_root.join(&receipt.path)).unwrap(),
        receipt_before
    );
    assert_eq!(
        git::run_stdout(
            &fixture.workspace,
            &["rev-parse", "HEAD"],
            "verify candidate"
        )
        .unwrap(),
        candidate_head_before
    );
    assert_eq!(
        git::run_stdout(
            &fixture.workspace,
            &["rev-list", "--reverse", "HEAD"],
            "verify candidate history after replay",
        )
        .unwrap(),
        candidate_history_before
    );
}

#[test]
fn queue_resume_requires_exact_legacy_learner_evidence() {
    use fluent::candidate_gate::{
        CANDIDATE_GATE_FILE, CandidateCheckEvidence, CandidateCheckStatus,
        CandidateGateDisposition, CandidateGateEvidence, CandidateGatePhase,
    };
    use fluent::queue::{self, DispatchStatus};
    use fluent::work_model::{
        AttemptLearning, AttemptReviewState, AttemptStatus, LearningFailureKind, TaskOutput,
        TaskStatus, WRITER_COMPLETION_CONTRACT_VERSION, WorkItem, WorkModelStore,
        WriterCompletionContract, WriterCompletionRequirement, WriterCompletionRequirementKind,
    };

    let tmp = TempDir::new().unwrap();
    let store = WorkModelStore::new(tmp.path());
    let mut item = WorkItem::planned("wi-legacy-evidence", "Recover Tester evidence");
    item.add_initial_attempt("attempt-1").unwrap();
    let writer = &mut item.attempts[0].tasks[0];
    writer.status = TaskStatus::Complete;
    writer.output = Some(TaskOutput {
        workspace_id: "candidate".to_string(),
        workspace_path: "../candidate".to_string(),
        source_branch: "main".to_string(),
        base_commit: Some("abc123".to_string()),
        commit: "abc123".to_string(),
        no_change: None,
        learner_canonicalization: None,
    });
    item.attempts[0].writer_completion_contract = Some(WriterCompletionContract {
        version: WRITER_COMPLETION_CONTRACT_VERSION,
        requirements: vec![WriterCompletionRequirement {
            responsibility: None,
            id: "behavior:b1".to_string(),
            kind: WriterCompletionRequirementKind::Behavior,
            source: "behaviors.md#b1".to_string(),
            requirement: "Preserve behavior".to_string(),
            verification_refs: vec!["tests/behavior.rs::required_behavior".to_string()],
            command: None,
        }],
    });
    item.add_final_tester_task("attempt-1").unwrap();
    item.attempts[0]
        .tasks
        .iter_mut()
        .find(|task| task.role == "tester")
        .unwrap()
        .status = TaskStatus::Complete;
    store.create_work_item(&item).unwrap();

    queue::add(tmp.path(), "wi-legacy-evidence", None).unwrap();
    let token = queue::claim(tmp.path(), "wi-legacy-evidence", "attempt-1")
        .unwrap()
        .unwrap();
    let token = queue::mark_running(tmp.path(), &token).unwrap();
    store
        .mutate_work_item("wi-legacy-evidence", |item| {
            let attempt = &mut item.attempts[0];
            attempt.status = AttemptStatus::Complete;
            attempt.review_state = Some(AttemptReviewState::Passed);
            attempt.learning = Some(AttemptLearning::failed_with_kind(
                1,
                "Learner candidate gate rejected abc123",
                LearningFailureKind::Generic,
            ));
            item.create_or_get_merge_candidate("attempt-1")?;
            Ok(())
        })
        .unwrap();

    let item = store.read_work_item("wi-legacy-evidence").unwrap();
    let tester = item.attempts[0]
        .tasks
        .iter()
        .find(|task| task.role == "tester")
        .unwrap();
    let tester_results_path = tmp
        .path()
        .join(&tester.artifact_area.as_ref().unwrap().path)
        .join("tester-results.json");
    fs::create_dir_all(tester_results_path.parent().unwrap()).unwrap();
    fs::write(&tester_results_path, "{}\n").unwrap();
    let tester_results_relative = tester_results_path
        .strip_prefix(tmp.path())
        .unwrap()
        .to_string_lossy()
        .to_string();
    let gate_path = tmp
        .path()
        .join(fluent::learner::handoff_dir_rel(
            "wi-legacy-evidence",
            "attempt-1",
        ))
        .join("runs/run-1")
        .join(CANDIDATE_GATE_FILE);
    fs::create_dir_all(gate_path.parent().unwrap()).unwrap();
    let runs_dir = gate_path.parent().unwrap().parent().unwrap();
    fs::create_dir_all(runs_dir.join("run-2")).unwrap();
    fs::create_dir_all(runs_dir.join("run-3")).unwrap();
    let checks = [
        ("candidate-identity", CandidateCheckStatus::Passed),
        ("whitespace", CandidateCheckStatus::Passed),
        ("commit-metadata", CandidateCheckStatus::Passed),
        ("behavior-references", CandidateCheckStatus::Passed),
        ("tester-reference-evidence", CandidateCheckStatus::Failed),
        ("project-check", CandidateCheckStatus::Skipped),
    ]
    .into_iter()
    .map(|(name, status)| CandidateCheckEvidence {
        name: name.to_string(),
        status,
        diagnostics: (name == "tester-reference-evidence")
            .then(|| vec!["no passing Tester result matches required_behavior".to_string()])
            .unwrap_or_default(),
        log_path: None,
    })
    .collect();
    let exact_evidence = CandidateGateEvidence {
        schema_version: 2,
        phase: CandidateGatePhase::Learner,
        disposition: CandidateGateDisposition::Rejected,
        base_commit: "abc123".to_string(),
        candidate_commit: "learner123".to_string(),
        tester_results_path: Some(tester_results_relative),
        metadata_rewrite: None,
        checks,
    };
    let mut incomplete_evidence = exact_evidence.clone();
    incomplete_evidence
        .checks
        .retain(|check| check.name != "project-check");
    fs::write(
        &gate_path,
        serde_json::to_vec_pretty(&incomplete_evidence).unwrap(),
    )
    .unwrap();
    queue::reconcile(tmp.path(), &token, DispatchStatus::CandidateReady).unwrap();

    fluent_cmd()
        .current_dir(tmp.path())
        .args([
            "queue",
            "resume",
            "wi-legacy-evidence",
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .failure();
    let ledger = queue::read_ledger(tmp.path(), "wi-legacy-evidence")
        .unwrap()
        .unwrap();
    assert_eq!(ledger.dispatches.len(), 1);
    assert_eq!(ledger.dispatches[0].status, DispatchStatus::CandidateReady);

    fs::write(
        &gate_path,
        serde_json::to_vec_pretty(&exact_evidence).unwrap(),
    )
    .unwrap();
    fluent_cmd()
        .current_dir(tmp.path())
        .args([
            "queue",
            "resume",
            "wi-legacy-evidence",
            "--attempt",
            "attempt-1",
        ])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Queued resume of Attempt attempt-1 for Work Item wi-legacy-evidence",
        ));
    let ledger = queue::read_ledger(tmp.path(), "wi-legacy-evidence")
        .unwrap()
        .unwrap();
    assert_eq!(ledger.dispatches[0].status, DispatchStatus::CandidateReady);
    assert_eq!(
        ledger.active().unwrap().bound_attempt_id.as_deref(),
        Some("attempt-1")
    );
}

#[test]
fn candidate_gate_pause_reports_and_accepts_exact_queue_resume() {
    use fluent::queue::{self, DispatchStatus};
    use fluent::work_model::{
        AttemptReviewState, AttemptStatus, PauseKind, WorkItem, WorkModelStore,
    };

    let tmp = TempDir::new().unwrap();
    let store = WorkModelStore::new(tmp.path());
    let mut item = WorkItem::planned("wi-gate", "Resume candidate gate");
    item.add_initial_attempt("attempt-1").unwrap();
    store.create_work_item(&item).unwrap();
    queue::add(tmp.path(), "wi-gate", Some(2)).unwrap();
    queue::claim(tmp.path(), "wi-gate", "attempt-1")
        .unwrap()
        .unwrap();
    store
        .mutate_work_item("wi-gate", |item| {
            let attempt = &mut item.attempts[0];
            attempt.status = AttemptStatus::NeedsUser;
            attempt.pause_kind = Some(PauseKind::CandidateGate);
            attempt.review_state = Some(AttemptReviewState::NotReviewed);
            Ok(())
        })
        .unwrap();
    queue::reconcile_active(tmp.path(), "wi-gate", DispatchStatus::NeedsUser).unwrap();

    fluent_cmd()
        .current_dir(tmp.path())
        .args(["work-item", "show", "wi-gate"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "\"pause_kind\": \"candidate-gate\"",
        ))
        .stderr(predicate::str::contains(
            "fluent queue resume wi-gate --attempt attempt-1",
        ));

    fluent_cmd()
        .current_dir(tmp.path())
        .args(["queue", "resume", "wi-gate", "--attempt", "attempt-1"])
        .assert()
        .success()
        .stdout(predicate::str::contains(
            "Queued resume of Attempt attempt-1 for Work Item wi-gate",
        ));
    let ledger = queue::read_ledger(tmp.path(), "wi-gate").unwrap().unwrap();
    assert_eq!(ledger.dispatches.len(), 2);
    assert_eq!(
        ledger.active().unwrap().bound_attempt_id.as_deref(),
        Some("attempt-1")
    );
}

