#[cfg(unix)]
#[test]
fn attempt_evidence_attach_revalidates_after_landing_owner_releases_lock() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, review_path, evidence) =
        setup_failed_evidence_recovery_fixture(&tmp, "evidence-landing");
    let land_guard = fluent::land_lock::acquire(&fluent::land_lock::lock_path(&project)).unwrap();
    let started = tmp.path().join("attachment-started");
    let mut command = Command::new("sh");
    let mut child = command
        .current_dir(&project)
        .args([
            "-c",
            "touch \"$1\"; shift; exec \"$@\"",
            "evidence-attach-wrapper",
            started.to_str().unwrap(),
            env!("CARGO_BIN_EXE_fluent"),
            "attempt",
            "evidence",
            "attach",
            "evidence-landing",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &review_path,
        ])
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_TEST_HERMETIC_PROVIDERS", "1")
        .env_remove("ANTHROPIC_API_KEY")
        .env_remove("ANTHROPIC_AUTH_TOKEN")
        .env_remove("CLAUDE_CODE_OAUTH_TOKEN")
        .env_remove("OPENAI_API_KEY")
        .env_remove("PI_API_KEY")
        .spawn()
        .unwrap();
    for _ in 0..100 {
        if started.exists() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    assert!(started.exists(), "attachment process did not start");
    assert!(
        child.try_wait().unwrap().is_none(),
        "attachment must wait while the landing owner holds the shared boundary"
    );

    let item_path = project.join(".fluent/work/items/evidence-landing.json");
    let after_landing_owner = fs::read_to_string(&item_path).unwrap();
    git::run(
        &project,
        &["commit", "--allow-empty", "-m", "Advance landing frontier"],
        "advance landing frontier",
    )
    .unwrap();
    assert_ne!(git_head(&project), candidate);
    drop(land_guard);

    let output = child.wait_with_output().unwrap();
    assert!(
        !output.status.success(),
        "attachment must reject the frontier published by the landing owner"
    );
    assert_json_unchanged(&item_path, &after_landing_owner);
    assert!(
        !project
            .join(".fluent/work/artifacts/evidence-landing/attempt-1/host-evidence")
            .exists()
    );
}

#[test]
fn work_show_explains_evidence_only_recovery_history_and_next_action() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, review_path, evidence) =
        setup_failed_evidence_recovery_fixture(&tmp, "evidence-show");
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-show",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            evidence.to_str().unwrap(),
            "--review-artifact",
            &review_path,
        ])
        .assert()
        .success();
    let store = fluent::work_model::WorkModelStore::new(&project);
    let targeted_path = store
        .mutate_work_item("evidence-show", |item| {
            let targeted = item.attempts[0].tasks.last_mut().unwrap();
            targeted.status = fluent::work_model::TaskStatus::Complete;
            Ok(targeted.artifact_area.as_ref().unwrap().path.clone())
        })
        .unwrap();
    fs::create_dir_all(project.join(&targeted_path)).unwrap();
    fs::write(
        project.join(&targeted_path).join("review.md"),
        "Verdict: fail\nDisposition: evidence-needed\nExternal-Condition: Restore the host launch network.\nAdditional-Proof: Attach a rerun after restoring it.\n",
    )
    .unwrap();
    let targeted_review_path = format!("{targeted_path}/review.md");

    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "run",
            "evidence-show",
            "attempt-1",
            "--no-sandbox",
        ])
        .assert()
        .success()
        .stderr(predicate::str::contains(format!(
            "fluent attempt evidence attach evidence-show attempt-1 --candidate {candidate} --evidence-file <path> --review-artifact {targeted_review_path}"
        )));

    let output = fluent_cmd()
        .current_dir(&project)
        .args(["work-item", "show", "evidence-show"])
        .output()
        .unwrap();
    assert!(output.status.success());
    let shown: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let attempt = &shown["attempts"][0];
    assert_eq!(attempt["status"], "needs-user");
    assert_eq!(attempt["pause_kind"], "uncertain");
    assert_eq!(attempt["evidence_recoveries"][0]["state"], "needs-evidence");
    assert!(attempt["tasks"].as_array().unwrap().iter().any(|task| {
        task["kind"] == "write" && task["status"] == "failed" && task["output"].is_null()
    }));
    assert_eq!(
        attempt["evidence_recoveries"][0]["targets"][0]["prior_review_artifact"],
        review_path
    );
    let guidance = String::from_utf8(output.stderr).unwrap();
    assert!(guidance.contains("fluent attempt evidence attach evidence-show attempt-1"));
    assert!(guidance.contains(&candidate));
    assert!(guidance.contains(&targeted_review_path));

    let successor_evidence = tmp.path().join("successor-evidence.json");
    fs::write(
        &successor_evidence,
        br#"{"schema_version":1,"producer":"host","check":"check","working_directory":"/repo","result":"pass","run_at":"2026-08-03T18:00:47Z","output":"passing successor"}"#,
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "attach",
            "evidence-show",
            "attempt-1",
            "--candidate",
            &candidate,
            "--evidence-file",
            successor_evidence.to_str().unwrap(),
            "--review-artifact",
            &targeted_review_path,
        ])
        .assert()
        .success();

    let shown = work_item_value(&project, "evidence-show");
    let attempt = &shown["attempts"][0];
    assert_eq!(attempt["status"], "reviewing");
    assert_eq!(attempt["evidence_recoveries"].as_array().unwrap().len(), 2);
    assert_eq!(attempt["evidence_recoveries"][0]["state"], "needs-evidence");
    assert_eq!(attempt["evidence_recoveries"][1]["state"], "reviewing");
    assert_eq!(
        attempt["evidence_recoveries"][1]["targets"][0]["prior_review_artifact"],
        targeted_review_path
    );
}

#[test]
fn failed_host_evidence_can_be_classified_for_code_change() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, prior_review_path, targeted_path, digest, snapshot_path) =
        setup_paused_code_change_classification_fixture(&tmp, "evidence-classify");
    let resolution = "The failed candidate-bound check needs a source correction.";
    let before = work_item_value(&project, "evidence-classify");
    let before_persisted = persisted_work_snapshot(&project, "evidence-classify");
    let before_targeted_review = fs::read(project.join(&targeted_path)).unwrap();
    let before_evidence = fs::read(project.join(&snapshot_path)).unwrap();
    let target_task_id = before["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| {
            task["artifact_area"]["path"]
                .as_str()
                .is_some_and(|path| format!("{path}/review.md") == targeted_path)
        })
        .and_then(|task| task["id"].as_str())
        .unwrap()
        .to_string();
    let first_output = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            "evidence-classify",
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &digest,
            "--resolution",
            resolution,
        ])
        .output()
        .unwrap();
    assert!(
        first_output.status.success(),
        "classification failed: stdout={} stderr={}",
        String::from_utf8_lossy(&first_output.stdout),
        String::from_utf8_lossy(&first_output.stderr)
    );
    let first_stdout = first_output.stdout.clone();
    let first_stdout_text = String::from_utf8(first_stdout.clone()).unwrap();
    let next_command = first_stdout_text
        .lines()
        .find_map(|line| line.strip_prefix("Next: "))
        .expect("classification must emit a queue-resume next command");
    assert_eq!(
        next_command,
        "fluent queue resume evidence-classify --attempt attempt-1"
    );
    let next_args = next_command.split_whitespace().skip(1).collect::<Vec<_>>();
    fluent_cmd()
        .current_dir(&project)
        .args(next_args)
        .assert()
        .success();
    let shown = work_item_value(&project, "evidence-classify");
    let attempt = &shown["attempts"][0];
    assert_eq!(attempt["status"], "planned");
    assert_eq!(attempt["evidence_recoveries"][0]["state"], "code-change");
    let classification = &attempt["evidence_recoveries"][0]["code_change_classification"];
    assert_eq!(classification["review_artifact"], targeted_path);
    assert_eq!(classification["authorization"], resolution);
    assert_eq!(classification["disposition"], "code-change");
    assert_eq!(
        classification["authorization_digest"],
        format!("sha256:{:x}", sha2::Sha256::digest(resolution.as_bytes()))
    );
    assert_eq!(
        classification["review_digest"].as_str().unwrap(),
        format!(
            "sha256:{:x}",
            sha2::Sha256::digest(fs::read(project.join(&targeted_path)).unwrap())
        )
    );
    assert!(
        project
            .join(classification["audit_artifact"]["path"].as_str().unwrap())
            .exists()
    );
    let audit_path = classification["audit_artifact"]["path"].as_str().unwrap();
    let audit_bytes = fs::read(project.join(audit_path)).unwrap();
    let audit_directory = Path::new(audit_path).parent().unwrap().to_path_buf();
    let audit: serde_json::Value = serde_json::from_slice(&audit_bytes).unwrap();
    assert_eq!(audit["evidence"]["snapshot_path"], snapshot_path);
    assert_eq!(audit["evidence"]["digest"], digest);
    assert_eq!(audit["review_artifact"], targeted_path);
    assert_eq!(audit["review_digest"], classification["review_digest"]);
    assert_eq!(audit["disposition"], "code-change");
    assert_eq!(audit["authorization"], resolution);
    assert_eq!(
        audit["authorization_digest"],
        classification["authorization_digest"]
    );
    let writer = attempt["tasks"].as_array().unwrap().last().unwrap();
    assert_eq!(writer["kind"], "write");
    let inputs = writer["input_artifacts"].as_array().unwrap();
    assert!(
        inputs.iter().any(|input| {
            input["producer_id"] == target_task_id && input["path"] == targeted_path
        })
    );
    assert!(inputs.iter().any(|input| {
        input["producer_id"] == "host-evidence" && input["path"] == snapshot_path
    }));
    assert!(
        inputs
            .iter()
            .any(|input| { input == &classification["audit_artifact"] })
    );
    assert_eq!(attempt["evidence_recoveries"].as_array().unwrap().len(), 1);
    assert_eq!(git_head(&project), candidate);
    let after_first_persisted = persisted_work_snapshot(&project, "evidence-classify");
    for before_entry in &before_persisted {
        let is_mutable_aggregate = before_entry.path
            == PathBuf::from(".fluent/work/items/evidence-classify.json")
            || before_entry
                .path
                .starts_with(".fluent/work/attempts/evidence-classify/");
        if is_mutable_aggregate {
            continue;
        }
        let after_entry = after_first_persisted
            .iter()
            .find(|entry| entry.path == before_entry.path)
            .unwrap_or_else(|| {
                panic!(
                    "historical entry disappeared: {}",
                    before_entry.path.display()
                )
            });
        assert_eq!(
            after_entry.kind,
            before_entry.kind,
            "kind changed for {}",
            before_entry.path.display()
        );
        assert_eq!(
            after_entry.bytes,
            before_entry.bytes,
            "bytes changed for {}",
            before_entry.path.display()
        );
    }
    assert_eq!(
        fs::read(project.join(&targeted_path)).unwrap(),
        before_targeted_review
    );
    assert_eq!(
        fs::read(project.join(&snapshot_path)).unwrap(),
        before_evidence
    );
    let before_attempt = &before["attempts"][0];
    let after_attempt = attempt;
    for before_task in before_attempt["tasks"].as_array().unwrap() {
        let task_id = before_task["id"].as_str().unwrap();
        let after_task = after_attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|task| task["id"] == task_id)
            .unwrap_or_else(|| panic!("historical Task disappeared: {task_id}"));
        assert_eq!(
            after_task, before_task,
            "Task history changed for {task_id}"
        );
    }
    let before_recovery = &before_attempt["evidence_recoveries"][0];
    let after_recovery = &after_attempt["evidence_recoveries"][0];
    assert_eq!(after_recovery["id"], before_recovery["id"]);
    assert_eq!(
        after_recovery["candidate_commit"],
        before_recovery["candidate_commit"]
    );
    assert_eq!(after_recovery["attachment"], before_recovery["attachment"]);
    assert_eq!(
        after_recovery["targets"][0]["prior_review_artifact"],
        before_recovery["targets"][0]["prior_review_artifact"]
    );
    assert_eq!(
        after_recovery["targets"][0]["role"],
        before_recovery["targets"][0]["role"]
    );
    assert_eq!(
        after_recovery["targets"][0]["review_task_id"],
        before_recovery["targets"][0]["review_task_id"]
    );
    let writer_task_id = classification["writer_task_id"].as_str().unwrap();
    let mut added_paths = after_first_persisted
        .iter()
        .filter(|entry| {
            !before_persisted
                .iter()
                .any(|before| before.path == entry.path)
        })
        .map(|entry| entry.path.clone())
        .collect::<Vec<_>>();
    added_paths.sort();
    let mut expected_added_paths = vec![
        audit_directory,
        PathBuf::from(audit_path),
        PathBuf::from(format!(
            ".fluent/work/tasks/evidence-classify/attempt-1/{writer_task_id}.json"
        )),
    ];
    expected_added_paths.sort();
    assert_eq!(added_paths, expected_added_paths);
    let first_model = shown.clone();
    let first_snapshot = persisted_work_snapshot(&project, "evidence-classify");
    let first_audit_bytes = audit_bytes.clone();

    let second_output = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            "evidence-classify",
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &digest,
            "--resolution",
            "The failed candidate-bound check needs a source correction.",
        ])
        .output()
        .unwrap();
    assert!(second_output.status.success());
    assert_eq!(second_output.stdout, first_stdout);
    let repeated = work_item_value(&project, "evidence-classify");
    assert_eq!(repeated, first_model);
    assert_eq!(
        persisted_work_snapshot(&project, "evidence-classify"),
        first_snapshot
    );
    assert_eq!(
        fs::read(project.join(audit_path)).unwrap(),
        first_audit_bytes
    );
    assert_eq!(git_head(&project), candidate);

    let rejected = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            "evidence-classify",
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &digest,
            "--resolution",
            "Authorize a different correction.",
        ])
        .output()
        .unwrap();
    assert!(!rejected.status.success());
    assert_eq!(
        persisted_work_snapshot(&project, "evidence-classify"),
        first_snapshot
    );
    assert_eq!(
        fs::read(project.join(audit_path)).unwrap(),
        first_audit_bytes
    );
    assert_eq!(git_head(&project), candidate);
    assert!(prior_review_path.starts_with(".fluent/work/artifacts/"));
}

#[test]
fn host_evidence_classification_rejects_passing_snapshot_without_mutation() {
    let tmp = TempDir::new().unwrap();
    let (project, candidate, _prior_review_path, targeted_path, digest, _snapshot_path) =
        setup_paused_code_change_classification_fixture_with_result(
            &tmp,
            "evidence-classify-passing",
            "pass",
        );
    let resolution = "The failed candidate-bound check needs a source correction.";
    let before = work_item_value(&project, "evidence-classify-passing");
    let before_persisted = persisted_work_snapshot(&project, "evidence-classify-passing");
    let head_before = git_head(&project);

    let output = fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "classify",
            "evidence-classify-passing",
            "attempt-1",
            "--candidate",
            &candidate,
            "--review-artifact",
            &targeted_path,
            "--evidence-digest",
            &digest,
            "--resolution",
            resolution,
        ])
        .output()
        .unwrap();
    assert!(
        !output.status.success(),
        "classification accepted passing evidence: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        String::from_utf8_lossy(&output.stderr).contains("evidence snapshot result must be fail")
    );
    assert_eq!(
        work_item_value(&project, "evidence-classify-passing"),
        before,
        "passing evidence classification changed the Work Item"
    );
    assert_eq!(
        persisted_work_snapshot(&project, "evidence-classify-passing"),
        before_persisted,
        "passing evidence classification changed persisted artifacts"
    );
    assert_eq!(
        git_head(&project),
        head_before,
        "passing evidence classification changed the candidate"
    );
}

