#[test]
fn attempt_run_prints_resolved_coder_plan() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin");
    write_mock_claude(
        &bin_dir,
        r##"#!/bin/bash
printf 'task output\n' > task-output.txt
git add task-output.txt
git commit -m "Add task output" >/dev/null
exit 0
"##,
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "plan-print", "--title", "Plan print"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "plan-print", "attempt-1"])
        .assert()
        .success();

    let output = fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "attempt",
            "run",
            "plan-print",
            "--no-sandbox",
            "--write-model",
            "my-model",
            "--effort",
            "high",
        ])
        .env("PATH", mock_path(&bin_dir))
        .output()
        .unwrap();

    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        stderr.contains("Coder plan:"),
        "should print coder plan header; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("writer") && stderr.contains("my-model"),
        "should show writer model; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("effort=high"),
        "should show effort; stderr:\n{stderr}"
    );

    // Verify FLUENT_QUIET suppresses it.
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "plan-print", "attempt-2"])
        .assert()
        .success();

    let quiet_output = fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "plan-print", "attempt-2", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .env("FLUENT_QUIET", "1")
        .output()
        .unwrap();

    let quiet_stderr = String::from_utf8_lossy(&quiet_output.stderr);
    assert!(
        !quiet_stderr.contains("Coder plan:"),
        "FLUENT_QUIET should suppress coder plan; stderr:\n{quiet_stderr}"
    );
}

#[test]
fn attempt_coder_model_flags_override_config() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);

    // Write a project config that sets writer to codex with a specific model.
    let config_dir = main_dir.join(".fluent");
    fs::create_dir_all(&config_dir).unwrap();
    fs::write(
        config_dir.join("config.yaml"),
        "coders:\n  writer:\n    coder: codex\n    model: config-model\n    effort: low\n",
    )
    .unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "override-test",
            "--title",
            "Override",
        ])
        .assert()
        .success();

    // Create attempt with CLI flags that override the config.
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "attempt",
            "create",
            "override-test",
            "attempt-1",
            "--write-model",
            "cli-model",
            "--effort",
            "high",
        ])
        .assert()
        .success();

    let value = work_item_value(&main_dir, "override-test");
    let mapping = &value["attempts"][0]["coder_mapping"];

    // --write-model should override the config model for write.
    assert_eq!(
        mapping["write"]["model"], "cli-model",
        "CLI --write-model should override config"
    );
    // Coder should still come from config since no CLI coder override.
    assert_eq!(
        mapping["write"]["coder"], "codex",
        "config coder used when CLI does not override"
    );
    // --effort (global) should apply to both roles.
    assert_eq!(
        mapping["write"]["effort"], "high",
        "CLI --effort should override config effort for write"
    );
    assert_eq!(
        mapping["review"]["effort"], "high",
        "CLI --effort should apply to review"
    );
    assert!(mapping.get("behavior-tests").is_none());
}

fn create_attempt_with_distinct_coder_mapping(main_dir: &Path, work_item_id: &str) {
    fluent_cmd()
        .current_dir(main_dir)
        .args([
            "work-item",
            "create",
            work_item_id,
            "--title",
            "Coder mapping continuity",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(main_dir)
        .args([
            "attempt",
            "create",
            work_item_id,
            "attempt-1",
            "--write-coder",
            "codex",
            "--write-model",
            "stored-write-model",
            "--write-effort",
            "high",
            "--review-coder",
            "pi",
            "--review-model",
            "stored-review-model",
            "--review-effort",
            "medium",
        ])
        .assert()
        .success();
}

fn replace_coder_config(main_dir: &Path) {
    fs::write(
        main_dir.join(".fluent/config.yaml"),
        "coders:\n  writer:\n    coder: claude\n    model: config-write\n    effort: low\n  reviewer:\n    coder: claude\n    model: config-review\n    effort: low\n",
    )
    .unwrap();
}

fn install_failing_coder_stubs(bin_dir: &Path) {
    // Autonomous Codex must retain its Seatbelt boundary even when the caller
    // requests --no-sandbox. The test fixture supplies a transparent launcher
    // so the deterministic coder failure, rather than host sandbox support,
    // remains the behavior under test.
    write_mock_sandbox_exec(bin_dir);
    for (coder, exit_code) in [("claude", 71), ("codex", 72), ("pi", 73)] {
        write_mock_executable(
            bin_dir,
            coder,
            &format!(
                r#"#!/bin/bash
if [[ "$*" == *"login status"* ]]; then
  exit 0
fi
if [[ "$*" == "--version" ]]; then
  exit 0
fi
{{
  printf 'coder={coder}\n'
  printf 'arg=%s\n' "$@"
}} >> "$FLUENT_TEST_CODER_INVOCATION"
exit {exit_code}
"#
            ),
        );
    }
}

fn assert_stored_writer_invocation(bin_dir: &Path) {
    let invocation = fs::read_to_string(bin_dir.join("invocation")).unwrap();
    assert!(
        invocation.starts_with("coder=codex\n"),
        "stored writer coder should run; invocation:\n{invocation}"
    );
    assert!(
        invocation.contains("arg=--model\narg=stored-write-model\n"),
        "stored writer model should reach Codex; invocation:\n{invocation}"
    );
    assert!(
        invocation.contains("arg=-c\narg=model_reasoning_effort=high\n"),
        "stored writer effort should reach Codex; invocation:\n{invocation}"
    );
}

fn run_with_changed_coder_environment(
    main_dir: &Path,
    bin_dir: &Path,
    args: &[&str],
) -> std::process::Output {
    fluent_cmd()
        .current_dir(main_dir)
        .args(args)
        .env("PATH", mock_path(bin_dir))
        .env("OPENAI_API_KEY", "fluent-test-key")
        .env("FLUENT_TEST_CODER_INVOCATION", bin_dir.join("invocation"))
        .env("FLUENT_WRITE_CODER", "pi")
        .env("FLUENT_WRITE_MODEL", "env-write")
        .env("FLUENT_WRITE_EFFORT", "low")
        .env("FLUENT_REVIEW_CODER", "claude")
        .env("FLUENT_REVIEW_MODEL", "env-review")
        .env("FLUENT_REVIEW_EFFORT", "high")
        .output()
        .unwrap()
}

#[test]
fn attempt_run_without_overrides_preserves_stored_coder_mapping() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let token = run_token(&tmp);
    let work_item_id = format!("mapping{token}");
    let bin_dir = tmp.path().join("bin-mapping");
    install_failing_coder_stubs(&bin_dir);
    create_attempt_with_distinct_coder_mapping(&main_dir, &work_item_id);
    let before = work_item_value(&main_dir, &work_item_id)["attempts"][0]["coder_mapping"].clone();

    replace_coder_config(&main_dir);
    let output = run_with_changed_coder_environment(
        &main_dir,
        &bin_dir,
        &["attempt", "run", &work_item_id, "attempt-1", "--no-sandbox"],
    );
    assert!(
        !output.status.success(),
        "the distinct Codex stub should produce its deterministic failure"
    );
    assert_stored_writer_invocation(&bin_dir);

    let after = work_item_value(&main_dir, &work_item_id)["attempts"][0]["coder_mapping"].clone();
    assert_eq!(
        after, before,
        "a flagless run must keep the Attempt's creation-time mapping"
    );
    remove_sibling_worktrees(&main_dir, &token);
}

