fn rebase_codex_auth_preflight_precedes_task_creation() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    let bin_dir = tmp.path().join("bin-codex-rebase-auth-failure");
    let launch_marker = tmp.path().join("rebase-launched");
    write_mock_claude(&bin_dir, &rebase_mock_script("pass"));
    write_mock_executable(
        &bin_dir,
        "codex",
        &format!(
            "#!/bin/bash\nif [[ \"$*\" == *\"login status\"* ]]; then exit 1; fi\ntouch '{}'\n",
            launch_marker.display()
        ),
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-1",
            "--title",
            "Codex rebase auth",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("PATH", mock_path(&bin_dir))
        .assert()
        .success();
    commit_file(
        &main_dir,
        "target-only.txt",
        "target advanced\n",
        "Advance target",
    );

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "merge-candidate",
            "land",
            "work-1",
            "attempt-1-merge-candidate",
            "--no-sandbox",
            "--coder",
            "codex",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("OPENAI_API_KEY", "fluent-test-key")
        .assert()
        .failure()
        .stderr(predicates::str::contains("codex login"));

    let item = work_item_value(&main_dir, "work-1");
    let attempt = &item["attempts"][0];
    assert!(
        attempt["tasks"]
            .as_array()
            .unwrap()
            .iter()
            .all(|task| task["kind"] != "rebase"),
        "a failed preflight must not create an executing Rebase Task: {attempt}"
    );
    assert!(
        !launch_marker.exists(),
        "a failed authentication preflight must not launch the rebase coder"
    );
}

fn prepare_codex_worker_home_fixture(
    tmp: &TempDir,
    fixture_name: &str,
    exec_body: &str,
) -> (PathBuf, PathBuf, PathBuf) {
    let source_home = tmp.path().join(format!("source-codex-home-{fixture_name}"));
    let bin_dir = tmp
        .path()
        .join(format!("bin-codex-worker-home-{fixture_name}"));
    let invocation_log = tmp.path().join(format!("codex-invocations-{fixture_name}"));
    fs::create_dir_all(source_home.join("sessions")).unwrap();
    fs::write(source_home.join("auth.json"), "source authentication").unwrap();
    fs::write(source_home.join("config.toml"), "hooks = true").unwrap();
    fs::write(source_home.join("sessions/session.json"), "session").unwrap();
    write_mock_sandbox_exec(&bin_dir);
    write_mock_executable(
        &bin_dir,
        "codex",
        &format!(
            r##"#!/bin/bash
set -euo pipefail
test "$CODEX_HOME" != "$FLUENT_TEST_SOURCE_CODEX_HOME"
test -f "$CODEX_HOME/auth.json"
test "$(cat "$CODEX_HOME/auth.json")" = "source authentication"
test ! -e "$CODEX_HOME/config.toml"
test ! -e "$CODEX_HOME/sessions"
test "$0" = "{expected_launcher}"
if [[ "${{1:-}}" == "login" && "${{2:-}}" == "status" && -z "${{3:-}}" ]]; then
  printf 'preflight=%s\n' "$CODEX_HOME" >> "$FLUENT_TEST_CODEX_INVOCATIONS"
  exit 0
fi
printf 'exec=%s\n' "$CODEX_HOME" >> "$FLUENT_TEST_CODEX_INVOCATIONS"
{exec_body}
"##,
            expected_launcher = fs::canonicalize(&bin_dir).unwrap().join("codex").display(),
        ),
    );
    (source_home, bin_dir, invocation_log)
}

fn prepare_strict_codex_worker_home_fixture(
    tmp: &TempDir,
    fixture_name: &str,
    exec_body: &str,
) -> (PathBuf, PathBuf, PathBuf, PathBuf) {
    #[cfg(unix)]
    use std::os::unix::fs::symlink;

    let (source_home, bin_dir, invocation_log) =
        prepare_codex_worker_home_fixture(tmp, fixture_name, exec_body);
    let alias_parent = tmp.path().join(format!("aliases-{fixture_name}"));
    fs::create_dir_all(&alias_parent).unwrap();
    let source_alias = alias_parent.join("source-codex-home");
    let temporary_root = tmp.path().join(format!("worker-temp-real-{fixture_name}"));
    fs::create_dir_all(&temporary_root).unwrap();
    let temporary_alias = alias_parent.join("worker-temp");
    #[cfg(unix)]
    {
        symlink(&source_home, &source_alias).unwrap();
        symlink(&temporary_root, &temporary_alias).unwrap();
    }
    #[cfg(not(unix))]
    {
        fs::create_dir_all(&source_alias).unwrap();
        fs::create_dir_all(&temporary_alias).unwrap();
    }

    write_mock_executable(
        &bin_dir,
        "sandbox-exec",
        r##"#!/bin/bash
set -euo pipefail
trap 'printf "strict-failed=%s\\n" "$BASH_COMMAND" >> "$FLUENT_TEST_CODEX_INVOCATIONS"' ERR
EXPECTED_LAUNCHER=$(cd "$(dirname "$0")" && pwd -P)/codex
if [ "$#" -lt 4 ] || [ "$1" != "-f" ] || [ "$3" != "$EXPECTED_LAUNCHER" ]; then
  echo "unexpected sandbox-exec invocation: $*" >&2
  exit 64
fi
PROFILE="$2"
CANONICAL_SOURCE_HOME=$(cd "$FLUENT_TEST_SOURCE_CODEX_HOME" && pwd -P)
CANONICAL_WORKER_HOME=$(cd "$CODEX_HOME" && pwd -P)
test "$CODEX_HOME" = "$CANONICAL_WORKER_HOME"
grep -Fq "(allow file-write* (subpath \"$CODEX_HOME\"))" "$PROFILE"
grep -Fq "(deny file-read* (subpath \"$CANONICAL_SOURCE_HOME\"))" "$PROFILE"
grep -Fq "(deny file-write* (subpath \"$CANONICAL_SOURCE_HOME\"))" "$PROFILE"
grep -Fq "(allow file-read*  (subpath \"$EXPECTED_LAUNCHER\"))" "$PROFILE"
if grep -Fq '(allow file-write* (subpath "/private/var/folders"))' "$PROFILE" || \
   grep -Fq '(allow file-write* (subpath "/private/tmp"))' "$PROFILE"; then
  echo "strict profile restores shared temporary-directory writes" >&2
  exit 1
fi
printf 'strict=%s\n' "$CODEX_HOME" >> "$FLUENT_TEST_CODEX_INVOCATIONS"
shift 2
exec -- "$@"
"##,
    );

    (source_alias, bin_dir, invocation_log, temporary_alias)
}

fn assert_codex_worker_home_was_cleaned(source_home: &Path, invocation_log: &Path) {
    let invocations = fs::read_to_string(invocation_log).unwrap();
    let worker_home = invocations
        .lines()
        .find_map(|line| line.strip_prefix("exec="))
        .expect("Codex exec should receive the staged home");
    assert!(
        invocations.contains(&format!("preflight={worker_home}")),
        "authentication preflight and execution must use the same worker home: {invocations}"
    );
    assert_ne!(Path::new(worker_home), source_home);
    assert!(
        !Path::new(worker_home).exists(),
        "the worker home must be removed after the launch: {worker_home}"
    );
}

#[test]
fn autonomous_codex_reviewer_uses_and_removes_worker_home() {
    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    create_completed_work_attempt(&tmp, &main_dir);
    let (source_home, bin_dir, invocation_log) = prepare_codex_worker_home_fixture(
        &tmp,
        "reviewer",
        r##"PROMPT="${!#}"
candidate="$(printf '%s\n' "$PROMPT" | sed -n 's/^- Workspace: //p' | head -1)"
commit="$(printf '%s\n' "$PROMPT" | sed -n 's/^[[:space:]]*"candidate-commit": "\([^"]*\)",$/\1/p' | head -1)"
role="$(printf '%s\n' "$PROMPT" | sed -n 's/^[[:space:]]*"role": "\([^"]*\)",$/\1/p' | head -1)"
inspected="$(git -C "$candidate" ls-tree -r --name-only "$commit" | head -1)"
absolute="$candidate/$inspected"
printf 'Verdict: pass\n\nCodex review.\n' > review.md
jq -n \
  --arg commit "$commit" \
  --arg role "$role" \
  --arg path "$inspected" \
  '{"schema-version": 1, "candidate-commit": $commit, role: $role, inspections: [{path: $path, summary: "Synthetic Codex reviewer inspected this tracked candidate file."}]}' \
  > review-inspection.json
jq -cn \
  --arg absolute "$absolute" \
  '{type: "item.completed", item: {type: "command_execution", status: "completed", exit_code: 0, command: ("sed -n 1,40p " + $absolute)}}'"##,
    );

    let attempt_path = main_dir.join(".fluent/work/attempts/work-1/attempt-1.json");
    let mut attempt = read_json_value(&attempt_path);
    attempt["coder_mapping"]["review"]["coder"] = serde_json::json!("codex");
    write_json_value(&attempt_path, &attempt);
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["review", "work-1", "attempt-1"])
        .assert()
        .success();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "task",
            "run",
            "work-1",
            "attempt-1",
            "attempt-1-review-tests",
            "--no-sandbox",
        ])
        .env("PATH", mock_path(&bin_dir))
        .env("CODEX_HOME", &source_home)
        .env("FLUENT_TEST_SOURCE_CODEX_HOME", &source_home)
        .env("FLUENT_TEST_CODEX_INVOCATIONS", &invocation_log)
        .assert()
        .success();

    assert_codex_worker_home_was_cleaned(&source_home, &invocation_log);
}

