// B9: THE SYSTEM SHALL install and run the scheduler service only for the
// current user, without requiring administrator privileges or serving other users.
#[cfg(unix)]
#[test]
fn scheduler_service_installation_is_current_user_scoped() {
    use fluent::scheduler_service::{self, BuildIdentity, FakeServiceManager, ServiceManager};
    use std::os::unix::fs::PermissionsExt;

    let home = TempDir::new().unwrap();
    let project = TempDir::new().unwrap();

    // Assign and register the checkout using only the current user's home;
    // no administrator privilege is required.
    let identity = scheduler_service::assign_checkout_identity(project.path()).unwrap();
    scheduler_service::register_checkout(home.path(), project.path(), &identity).unwrap();

    // The state root must be confined to the user-private path.
    let state_root = scheduler_service::service_state_root(home.path());
    assert!(
        state_root.starts_with(home.path()),
        "state root must be under the user home, not a system-wide path"
    );
    let root_meta = fs::metadata(&state_root).unwrap();
    let root_mode = root_meta.permissions().mode() & 0o777;
    assert_eq!(
        root_mode, 0o700,
        "state root must be accessible only by the owner"
    );

    // The socket path must also be under the user-private state root.
    let sock = scheduler_service::socket_path(home.path());
    assert!(
        sock.starts_with(&state_root),
        "socket must be confined to the user-private state root"
    );

    // Install and start through a fake manager — no LaunchAgent, no admin privilege.
    let build = BuildIdentity {
        version: "0.1.0-b9".to_string(),
        hash: "testbuildidentity123".to_string(),
    };
    let manager = FakeServiceManager::new();
    manager
        .install_or_update(&std::path::PathBuf::from("/fake/exe"), &build, &sock)
        .unwrap();
    manager.start().unwrap();
    assert!(
        manager.is_running(),
        "service must be running after start without admin privileges"
    );
    manager.stop().unwrap();
}

#[test]
#[serial]
fn attempt_extend_binds_candidate_and_failed_review_bytes() {
    use fluent::work_model::{
        AttemptReviewState, AttemptStatus, PauseKind, TaskKind, TaskOutput, TaskStatus,
        set_task_terminal,
    };

    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["work-item", "create", "work-1", "--title", "Round cap"])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    let workspace_rel = fluent::work_model::initial_candidate_workspace_path("work-1", "attempt-1");
    let workspace = main_dir
        .parent()
        .unwrap()
        .join(workspace_rel.trim_start_matches("../"));
    git::run(
        &main_dir,
        &["worktree", "add", workspace.to_str().unwrap()],
        "create candidate workspace",
    )
    .unwrap();
    let store = WorkModelStore::new(&main_dir);
    let mut item = store.read_work_item("work-1").unwrap();
    set_task_terminal(&mut item.attempts[0].tasks[0], TaskStatus::Complete);
    item.attempts[0].tasks[0].output = Some(TaskOutput {
        workspace_id: "candidate".to_string(),
        workspace_path: workspace_rel,
        source_branch: "main".to_string(),
        base_commit: None,
        commit: git_head(&workspace),
        no_change: None,
        learner_canonicalization: None,
    });
    item.add_next_review_tasks("attempt-1", &["tests"]).unwrap();
    let mut review_path = None;
    for task in item.attempts[0]
        .tasks
        .iter_mut()
        .filter(|task| task.kind != TaskKind::Write)
    {
        task.status = TaskStatus::Complete;
        if task.kind == TaskKind::Review {
            let path = main_dir
                .join(&task.artifact_area.as_ref().unwrap().path)
                .join("review.md");
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, "Verdict: fail\n").unwrap();
            review_path = Some(path);
        }
    }
    item.attempts[0].status = AttemptStatus::NeedsUser;
    item.attempts[0].pause_kind = Some(PauseKind::RoundCap);
    item.attempts[0].review_state = Some(AttemptReviewState::Failed);
    store.write_work_item(&item).unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "attempt",
            "extend",
            "work-1",
            "attempt-1",
            "--additional-write-rounds",
            "1",
            "--resolution",
            "Preserve the reviewed contract.",
        ])
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
        .assert()
        .success()
        .stdout(predicate::str::contains("cap 1 -> 2"));

    let stored = store.read_work_item("work-1").unwrap();
    let extension = &stored.attempts[0].round_cap_extensions[0];
    assert_eq!(extension.old_cap, 1);
    assert_eq!(extension.new_cap, 2);
    assert_eq!(
        extension.human_resolution,
        "Preserve the reviewed contract."
    );
    assert_eq!(
        extension.human_resolution_digest,
        fluent::work_model::round_cap_resolution_digest(&extension.human_resolution)
    );
    assert_eq!(extension.failed_reviews.len(), 1);
    assert!(extension.failed_reviews[0].digest.starts_with("sha256:"));
    assert_eq!(
        stored.attempts[0].tasks.len(),
        2,
        "extending the cap records approval but does not plan work before attempt run"
    );

    let mut altered = stored.clone();
    altered.attempts[0].round_cap_extensions[0]
        .human_resolution
        .push_str(" Changed.");
    store.write_work_item(&altered).unwrap();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "stored human resolution no longer matches",
        ));
    let mut restored = store.read_work_item("work-1").unwrap();
    restored.attempts[0].round_cap_extensions[0] = extension.clone();
    store.write_work_item(&restored).unwrap();

    fs::write(
        review_path.unwrap(),
        "Verdict: fail\nchanged after approval\n",
    )
    .unwrap();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "run", "work-1", "attempt-1", "--no-sandbox"])
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
        .assert()
        .failure()
        .stderr(predicate::str::contains(
            "failed-correction bytes no longer match the approval",
        ));
}

#[test]
#[serial]
fn attempt_extend_counts_repeated_evidence_corrections() {
    use fluent::work_model::{
        ArtifactRef, AttemptReviewState, AttemptStatus, EvidenceAttachment, EvidenceRecovery,
        EvidenceRecoveryState, EvidenceReviewTarget, PauseKind, TaskKind, TaskOutput, TaskStatus,
        set_task_terminal,
    };

    let tmp = TempDir::new().unwrap();
    let main_dir = setup_git_project(&tmp);
    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "work-item",
            "create",
            "work-1",
            "--title",
            "Evidence correction cap",
        ])
        .assert()
        .success();
    fluent_cmd()
        .current_dir(&main_dir)
        .args(["attempt", "create", "work-1", "attempt-1"])
        .assert()
        .success();

    let workspace_rel = fluent::work_model::initial_candidate_workspace_path("work-1", "attempt-1");
    let workspace = main_dir
        .parent()
        .unwrap()
        .join(workspace_rel.trim_start_matches("../"));
    git::run(
        &main_dir,
        &["worktree", "add", workspace.to_str().unwrap()],
        "create candidate workspace",
    )
    .unwrap();
    let candidate = git_head(&workspace);
    let writer_output = || TaskOutput {
        workspace_id: "candidate".to_string(),
        workspace_path: workspace_rel.clone(),
        source_branch: "main".to_string(),
        base_commit: None,
        commit: candidate.clone(),
        no_change: None,
        learner_canonicalization: None,
    };

    let store = WorkModelStore::new(&main_dir);
    let mut item = store.read_work_item("work-1").unwrap();
    set_task_terminal(&mut item.attempts[0].tasks[0], TaskStatus::Complete);
    item.attempts[0].tasks[0].output = Some(writer_output());
    for round in 1..=2 {
        let review_path =
            format!(".fluent/work/artifacts/work-1/attempt-1/evidence-{round}-tests/review.md");
        item.attempts[0].evidence_recoveries.push(EvidenceRecovery {
            id: format!("evidence-{round}"),
            candidate_commit: candidate.clone(),
            attachment: EvidenceAttachment {
                snapshot_path: format!(
                    ".fluent/work/artifacts/work-1/attempt-1/evidence-{round}.json"
                ),
                digest: format!("sha256:evidence-{round}"),
            },
            targets: vec![EvidenceReviewTarget {
                role: "tests".to_string(),
                prior_review_artifact: review_path.clone(),
                review_task_id: Some(format!("attempt-1-evidence-{round}-tests")),
                review_digest: None,
            }],
            state: EvidenceRecoveryState::CodeChange,
            created_at: "2026-08-11T00:00:00Z".to_string(),
            code_change_classification: None,
        });
        let writer_id = item
            .add_next_write_round(
                "attempt-1",
                vec![ArtifactRef {
                    producer_id: format!("attempt-1-evidence-{round}-tests"),
                    path: review_path,
                }],
            )
            .unwrap();
        let writer = item.attempts[0]
            .tasks
            .iter_mut()
            .find(|task| task.id == writer_id)
            .unwrap();
        set_task_terminal(writer, TaskStatus::Complete);
        writer.output = Some(writer_output());
    }
    item.add_next_review_tasks("attempt-1", &["tests"]).unwrap();
    let review = item.attempts[0]
        .tasks
        .iter_mut()
        .rev()
        .find(|task| task.kind == TaskKind::Review)
        .unwrap();
    set_task_terminal(review, TaskStatus::Complete);
    let review_path = main_dir
        .join(&review.artifact_area.as_ref().unwrap().path)
        .join("review.md");
    fs::create_dir_all(review_path.parent().unwrap()).unwrap();
    fs::write(&review_path, "Verdict: fail\n").unwrap();
    item.attempts[0].status = AttemptStatus::NeedsUser;
    item.attempts[0].pause_kind = Some(PauseKind::RoundCap);
    item.attempts[0].review_state = Some(AttemptReviewState::Failed);
    store.write_work_item(&item).unwrap();

    fluent_cmd()
        .current_dir(&main_dir)
        .args([
            "attempt",
            "extend",
            "work-1",
            "attempt-1",
            "--additional-write-rounds",
            "1",
            "--resolution",
            "Keep evidence correction accounting stable.",
        ])
        .env("FLUENT_MAX_TOTAL_WRITE_ROUNDS", "1")
        .assert()
        .success()
        .stdout(predicate::str::contains("cap 3 -> 4"));

    let stored = store.read_work_item("work-1").unwrap();
    let attempt = &stored.attempts[0];
    assert_eq!(
        attempt
            .tasks
            .iter()
            .filter(|task| task.kind == TaskKind::Write)
            .count(),
        3
    );
    assert_eq!(attempt.effective_write_round_cap(1), 4);
    assert_eq!(attempt.round_cap_extensions[0].old_cap, 3);
    assert_eq!(attempt.round_cap_extensions[0].new_cap, 4);
}

