#[test]
fn verification_receipt_is_compact_immutable_and_candidate_bound() {
    let tmp = TempDir::new().unwrap();
    let work = "verification-receipt";
    let (project, area, candidate) = scheduled_verification_fixture(
        &tmp,
        work,
        "python3 -c 'import sys; sys.stdout.write(\"x\"*1000000); sys.stderr.write(\"y\"*1000000)'",
    );
    let bytes = fs::read(area.join("receipt.json")).unwrap();
    let receipt: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
    assert!(bytes.len() < 16 * 1024);
    assert_eq!(receipt["candidate_commit"], candidate);
    assert_eq!(receipt["result"], "pass");
    assert_eq!(receipt["exit_status"], 0);
    assert!(receipt["started_at"].is_string());
    assert!(receipt["completed_at"].is_string());
    for (index, name) in ["stdout.log", "stderr.log"].iter().enumerate() {
        let output = fs::read(area.join(name)).unwrap();
        assert_eq!(output.len(), 384 * 1024);
        use sha2::{Digest, Sha256};
        assert_eq!(
            receipt["artifacts"][index]["digest"],
            format!("sha256:{:x}", Sha256::digest(output))
        );
    }
    fluent_cmd()
        .current_dir(&project)
        .args(["task", "run", work, "attempt-1", "attempt-1-verification-1"])
        .assert()
        .failure();
    assert_eq!(fs::read(area.join("receipt.json")).unwrap(), bytes);
    accept_focused_verification(&project, work).unwrap();
    let shown = work_item_value(&project, work);
    assert_eq!(
        shown["attempts"][0]["evidence_recoveries"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert!(fs::metadata(area.join("evidence.json")).unwrap().len() < 2048);
    assert_eq!(git_head(&project), candidate);
}

#[test]
fn invalid_verification_receipt_blocks_then_corrected_receipt_advances() {
    let tmp = TempDir::new().unwrap();
    let work = "verification-invalid";
    let (project, area, candidate) =
        scheduled_verification_fixture(&tmp, work, "printf valid-output");
    let receipt_path = area.join("receipt.json");
    let bytes = fs::read(&receipt_path).unwrap();
    let original: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
    let before = work_item_value(&project, work);
    for field in [
        "candidate_commit",
        "command",
        "working_directory",
        "checker_digest",
        "task_id",
        "started_at",
        "completed_at",
    ] {
        let mut bad = original.clone();
        bad[field] = serde_json::json!("stale");
        fs::write(&receipt_path, serde_json::to_vec(&bad).unwrap()).unwrap();
        assert!(
            accept_focused_verification(&project, work).is_err(),
            "{field}"
        );
        assert_eq!(work_item_value(&project, work), before);
    }
    fs::write(&receipt_path, b"{").unwrap();
    assert!(accept_focused_verification(&project, work).is_err());
    fs::remove_file(&receipt_path).unwrap();
    assert!(accept_focused_verification(&project, work).is_err());
    fs::write(&receipt_path, &bytes).unwrap();
    let stdout = fs::read(area.join("stdout.log")).unwrap();
    fs::write(area.join("stdout.log"), b"changed artifact").unwrap();
    assert!(accept_focused_verification(&project, work).is_err());
    fs::write(area.join("stdout.log"), stdout).unwrap();
    let task = &before["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["kind"] == "verification")
        .unwrap();
    let review_path = project.join(
        task["verification_context"]["review_artifact"]["path"]
            .as_str()
            .unwrap(),
    );
    let review = fs::read(&review_path).unwrap();
    fs::write(&review_path, b"invalid fixture").unwrap();
    assert!(accept_focused_verification(&project, work).is_err());
    fs::write(&review_path, review).unwrap();
    assert_eq!(work_item_value(&project, work), before);
    assert_eq!(git_head(&project), candidate);
    accept_focused_verification(&project, work).unwrap();
    let after = work_item_value(&project, work);
    let reviews = after["attempts"][0]["tasks"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|task| task["evidence_review_context"].is_object())
        .collect::<Vec<_>>();
    assert_eq!(reviews.len(), 1);
    assert_eq!(reviews[0]["review_context"]["candidate_commit"], candidate);
}

#[test]
fn verification_worker_does_not_block_unrelated_attempt_progress() {
    let tmp = TempDir::new().unwrap();
    let (project, _, review) = setup_focused_evidence_fixture(
        &tmp,
        "verification-slow",
        "tests",
        "Verdict: fail\nEvidence-Command: python3 -c 'import os,time; p=os.environ[\"FLUENT_EVIDENCE_SCRATCH\"]; open(p+\"/started\",\"w\").close(); [time.sleep(.02) for _ in range(750) if not os.path.exists(p+\"/release\")]'\nEvidence-Working-Directory: .\n",
    );
    let (_, _, peer_review) = create_focused_evidence_item(
        project.clone(),
        "verification-peer",
        "tests",
        "Verdict: fail\nEvidence-Command: printf peer-progress\nEvidence-Working-Directory: .\n",
    );
    let bin = tmp.path().join("verification-bin");
    write_mock_executable(&bin, "sandbox-exec", "#!/bin/sh\nshift 2\nexec \"$@\"\n");
    fluent_cmd()
        .current_dir(&project)
        .args([
            "attempt",
            "evidence",
            "run",
            "verification-slow",
            "attempt-1",
            "--review-artifact",
            &review,
        ])
        .assert()
        .success();
    let mut worker = Command::new(assert_cmd::cargo::cargo_bin!("fluent"))
        .current_dir(&project)
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass")
        .env(
            "FLUENT_TEST_FOCUSED_EVIDENCE_SANDBOX_EXEC",
            bin.join("sandbox-exec"),
        )
        .args([
            "task",
            "run",
            "verification-slow",
            "attempt-1",
            "attempt-1-verification-1",
        ])
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .unwrap();
    let scratch = project.join(
        ".fluent/work/artifacts/verification-slow/attempt-1/attempt-1-verification-1/scratch",
    );
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while !scratch.join("started").exists() && std::time::Instant::now() < deadline {
        assert!(
            worker.try_wait().unwrap().is_none(),
            "verification exited before reaching the barrier"
        );
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    assert!(scratch.join("started").exists());
    // Scheduling takes the real project landing lock; command timeout catches a regression.
    assert_cmd::Command::new(assert_cmd::cargo::cargo_bin!("fluent"))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass")
        .current_dir(&project)
        .timeout(std::time::Duration::from_secs(3))
        .args([
            "attempt",
            "evidence",
            "run",
            "verification-peer",
            "attempt-1",
            "--review-artifact",
            &peer_review,
        ])
        .assert()
        .success();
    assert_cmd::Command::new(assert_cmd::cargo::cargo_bin!("fluent"))
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .env("FLUENT_TEST_HOST_SANDBOX_PREFLIGHT", "pass")
        .current_dir(&project)
        .timeout(std::time::Duration::from_secs(3))
        .env(
            "FLUENT_TEST_FOCUSED_EVIDENCE_SANDBOX_EXEC",
            bin.join("sandbox-exec"),
        )
        .args([
            "task",
            "run",
            "verification-peer",
            "attempt-1",
            "attempt-1-verification-1",
        ])
        .assert()
        .success();
    accept_focused_verification(&project, "verification-peer").unwrap();
    assert_eq!(
        work_item_value(&project, "verification-peer")["attempts"][0]["evidence_recoveries"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    assert!(
        worker.try_wait().unwrap().is_none(),
        "peer progressed before the slow verification finished"
    );
    fs::write(scratch.join("release"), "release").unwrap();
    assert!(worker.wait().unwrap().success());
}

#[test]
fn attempt_cancel_persists_stop_before_settling_active_execution() {
    use fluent::{execution, work_model::*};
    let tmp = TempDir::new().unwrap();
    let project = setup_git_project(&tmp);
    let store = WorkModelStore::new(&project);
    let mut item = WorkItem::planned("cancel-stop", "Cancel an active worker");
    item.add_initial_attempt("attempt-1").unwrap();
    let task = &mut item.attempts[0].tasks[0];
    task.status = TaskStatus::Executing;
    let area = project.join(&task.artifact_area.as_ref().unwrap().path);
    fs::create_dir_all(&area).unwrap();
    let transcript = area.join("transcript.jsonl");
    item.attempts[0].status = AttemptStatus::Executing;
    store.create_work_item(&item).unwrap();
    let ready = tmp.path().join("ready");
    let observed = tmp.path().join("signal-observation.json");
    let release = tmp.path().join("release");
    let mut command = Command::new("python3");
    command
        .args([
            "-c",
            r#"
import json, os, signal, sys, time
from pathlib import Path
attempt, ready, observed, release = map(Path, sys.argv[1:])

def on_term(signum, frame):
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    # Read the persisted Attempt when the first signal arrives, before allowing
    # this worker to exit and release its inherited execution ownership.
    state = json.loads(attempt.read_text())
    temporary = observed.with_suffix('.tmp')
    temporary.write_text(json.dumps(state.get('cancellation')))
    temporary.replace(observed)
    deadline = time.monotonic() + 120
    while not release.exists() and time.monotonic() < deadline:
        time.sleep(0.01)
    sys.exit(0)

signal.signal(signal.SIGTERM, on_term)
ready.touch()
time.sleep(120)
"#,
        ])
        .arg(store.work_attempt_path("cancel-stop", "attempt-1").unwrap())
        .arg(&ready)
        .arg(&observed)
        .arg(&release);
    execution::configure_identity_lock(&mut command, &transcript).unwrap();
    let mut child = OwnedFixtureProcess::spawn(&mut command);
    let _heartbeat = execution::ExecutionHeartbeat::start(&transcript, child.id()).unwrap();
    assert!(poll_until(std::time::Duration::from_secs(3), || ready.is_file()));
    let mut command = Command::new(assert_cmd::cargo::cargo_bin!("fluent"));
    command
        .current_dir(&project)
        .env("FLUENT_NO_UPDATE_CHECK", "1")
        .args(["attempt", "cancel", "cancel-stop", "attempt-1"])
        .stdout(std::process::Stdio::null());
    let mut cancel = OwnedFixtureProcess::spawn(&mut command);
    assert!(
        poll_until(std::time::Duration::from_secs(8), || observed.is_file()),
        "worker must observe the first cancellation signal"
    );
    let at_signal: serde_json::Value =
        serde_json::from_slice(&fs::read(&observed).unwrap()).unwrap();
    assert!(
        at_signal["requested_at"].is_string(),
        "durable stop must exist when the worker receives its first signal: {at_signal}"
    );
    assert!(at_signal["settled_at"].is_null());
    assert!(
        child.try_wait().unwrap().is_none(),
        "worker waits at the signal barrier"
    );
    assert!(
        cancel.try_wait().unwrap().is_none(),
        "cancel waits for worker settlement"
    );
    fs::write(&release, "settle").unwrap();
    assert!(
        poll_until(std::time::Duration::from_secs(8), || {
            cancel.try_wait().unwrap().is_some_and(|status| {
                assert!(status.success());
                true
            })
        }),
        "cancel must finish before the fixture's natural lifetime"
    );
    assert!(poll_until(std::time::Duration::from_secs(2), || child
        .try_wait()
        .unwrap()
        .is_some()));
    let after = work_item_value(&project, "cancel-stop");
    assert_eq!(after["attempts"][0]["status"], "needs-user");
    assert!(after["attempts"][0]["cancellation"]["settled_at"].is_string());
}

